// ====== Weaver Bundle ======
if (typeof window.W === "undefined") window.W = {};
// ==============================

// ---- js/storage/storage.js ----
// ===============================================================
//  Weaver Storage Layer
// ===============================================================

// CRITICAL: Initialize W namespace FIRST
window.W = window.W || {};

const StorageModule = (function () {
  const Storage = {
    _key(key) {
      return `weaver:${key}`;
    },

    set(key, value) {
      // Vault routing. When the vault is unlocked, set() updates the
      // sync cache synchronously and returns a Promise for the
      // encrypted write. Callers may ignore the Promise (fire-and-
      // forget) — the cache is already updated by the time set()
      // returns.
      if (W.vault && typeof W.vault.routingFor === "function") {
        const route = W.vault.routingFor(key);
        if (route === "vault") return W.vault.set(key, value);
      }
      try {
        localStorage.setItem(this._key(key), JSON.stringify(value));
      } catch (e) {
        console.warn("[Storage] set error:", e.message);
        if (!this._memory) this._memory = {};
        this._memory[key] = value;
      }
    },

    get(key, fallback = null) {
      // Vault routing — see js/lib/crypto/vault.js. Only meaningful
      // for keys on the vault list. Throws when the vault is locked
      // and the key is sensitive (no silent fallback to plaintext,
      // which would be empty after migration).
      if (W.vault && typeof W.vault.routingFor === "function") {
        const route = W.vault.routingFor(key);
        if (route === "vault") return W.vault.getCached(key, fallback);
      }
      try {
        const raw = localStorage.getItem(this._key(key));
        if (raw === null) {
          if (this._memory && key in this._memory) {
            return this._memory[key];
          }
          return fallback;
        }
        return JSON.parse(raw);
      } catch (e) {
        console.warn("[Storage] get error:", e.message);
        return fallback;
      }
    },

    delete(key) {
      if (W.vault && typeof W.vault.routingFor === "function") {
        const route = W.vault.routingFor(key);
        if (route === "vault") return W.vault.delete(key);
      }
      try {
        localStorage.removeItem(this._key(key));
        if (this._memory) delete this._memory[key];
      } catch (e) {
        console.warn("[Storage] delete error:", e.message);
      }
    },

    // Note: the legacy secure_settings store and its migration
    // helpers were removed — sensitive data now lives in the
    // "encrypted_settings" blob owned by W.secureSession. See
    // js/lib/crypto/secure-session.js.

    // ── IndexedDB placeholders ──────────────────────────────
    async openIndexedDB(dbName = "WeaverDB", version = 1) {
      return new Promise((resolve, reject) => {
        const request = indexedDB.open(dbName, version);
        request.onupgradeneeded = (e) => {
          const db = e.target.result;
          if (!db.objectStoreNames.contains("store")) {
            db.createObjectStore("store", { keyPath: "key" });
          }
        };
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
    },

    async saveToIndexedDB(key, value) {
      try {
        const db = await this.openIndexedDB();
        const tx = db.transaction("store", "readwrite");
        const store = tx.objectStore("store");
        store.put({ key, value });
        return new Promise((resolve, reject) => {
          tx.oncomplete = () => resolve();
          tx.onerror = () => reject(tx.error);
        });
      } catch (e) {
        console.warn("[Storage] IndexedDB save error:", e.message);
      }
    },

    async loadFromIndexedDB(key) {
      try {
        const db = await this.openIndexedDB();
        const tx = db.transaction("store", "readonly");
        const store = tx.objectStore("store");
        const request = store.get(key);
        return new Promise((resolve, reject) => {
          request.onsuccess = () => resolve(request.result?.value);
          request.onerror = () => reject(request.error);
        });
      } catch (e) {
        console.warn("[Storage] IndexedDB load error:", e.message);
        return null;
      }
    },
  };

  return Storage;
})();

// ── ALWAYS assign the proper storage module ──────────────────
W.store = StorageModule;
console.log("[Storage] Module loaded.");
// ---- js/storage/observations.js ----
// ===============================================================
//         Weaver Observations — time-series storage
// ===============================================================
//
// Persists market-structure observations keyed by chain+address,
// prunes them to a bounded retention window, and computes deltas
// against the past for a set of standard intervals (5m, 15m, 1h).
//
// DESIGN REFERENCE:
//   docs/trajectory-design.md
//
// STORAGE:
//   Uses W.store for persistence. Keys are:
//     obs:<chain>:<normalizedAddress>
//   Normalization matches shieldCacheKey: EVM lowercased, Solana
//   case-preserved.
//
// RETENTION:
//   Two constraints applied on every read and write:
//     - Time window: 2 hours
//     - Count cap: 30 observations per token
//
// DELTA COMPUTATION:
//   Half-interval tolerance. A 5-minute delta is computed only
//   against an observation whose observedAt falls within 2.5 minutes
//   of the target time (now - 5m). Outside tolerance, the delta is
//   null, never zero.
//
// FAILURE ISOLATION:
//   This module never throws. Storage errors, corrupt data, quota
//   exhaustion, and missing history all degrade to safe defaults
//   (empty arrays, null deltas, false return values). Errors are
//   logged once per session.
//
// NOT A RISK CLASSIFIER:
//   Direction labels ("rising" / "falling") are descriptors, not
//   judgments. W.shield.isHighRisk() remains the single authority
//   for risk classification.
// ===============================================================

window.W = window.W || {};

W.observations = (() => {
  const KEY_PREFIX = "obs:";
  const RETENTION_MS = 2 * 60 * 60 * 1000; // 2 hours
  const MAX_OBSERVATIONS = 30;
  const METHODOLOGY_VERSION = "trajectory-v1";
  const DIRECTION_THRESHOLD_PCT = 2;

  const INTERVALS = {
    change5m: 5 * 60 * 1000,
    change15m: 15 * 60 * 1000,
    change1h: 60 * 60 * 1000,
  };

  // Track warnings we've already emitted so a repeated storage error
  // does not spam the console on every scan. Matches the
  // warnedUnevaluable pattern in track-record.js.
  const warned = new Set();
  function warnOnce(tag, message) {
    if (warned.has(tag)) return;
    warned.add(tag);
    console.warn("[Observations]", message);
  }

  function key(chainKey, address) {
    if (typeof chainKey !== "string" || !chainKey) return null;
    if (typeof address !== "string" || !address.trim()) return null;
    const normalized = chainKey === "solana" ? address : address.toLowerCase();
    return KEY_PREFIX + chainKey + ":" + normalized;
  }

  function deepClone(value) {
    if (value === null || value === undefined) return value;
    try {
      if (typeof structuredClone === "function") return structuredClone(value);
    } catch (_) {}
    return JSON.parse(JSON.stringify(value));
  }

  function prune(list, now) {
    const cutoff = now - RETENTION_MS;
    let pruned = list.filter(
      (o) =>
        o &&
        typeof o === "object" &&
        Number.isFinite(o.observedAt) &&
        o.observedAt >= cutoff,
    );
    pruned.sort((a, b) => a.observedAt - b.observedAt);
    if (pruned.length > MAX_OBSERVATIONS) {
      pruned = pruned.slice(-MAX_OBSERVATIONS);
    }
    return pruned;
  }

  function history(chainKey, address) {
    const k = key(chainKey, address);
    if (!k) return [];
    let raw;
    try {
      raw = W.store?.get?.(k, []);
    } catch (e) {
      warnOnce("history-read", "Failed to read history: " + (e && e.message));
      return [];
    }
    if (!Array.isArray(raw)) return [];
    return prune(raw, Date.now());
  }

  function record(chainKey, address, observation) {
    const k = key(chainKey, address);
    if (!k) return false;
    if (!observation || typeof observation !== "object") return false;
    if (!Number.isFinite(observation.observedAt)) return false;

    const now = Date.now();
    const observedAt =
      observation.observedAt > now ? now : observation.observedAt;

    try {
      const existing = history(chainKey, address);
      // Idempotent: an observation with the same observedAt is not
      // duplicated. This matters when a rescan produces identical
      // timestamps — the history should not grow without bound.
      if (existing.some((o) => o.observedAt === observedAt)) {
        return true;
      }
      const normalized = deepClone({ ...observation, observedAt });
      const next = prune([...existing, normalized], now);
      W.store?.set?.(k, next);
      return true;
    } catch (e) {
      warnOnce(
        "record-write",
        "Failed to record observation: " + (e && e.message),
      );
      return false;
    }
  }

  function clear(chainKey, address) {
    const k = key(chainKey, address);
    if (!k) return false;
    try {
      W.store?.delete?.(k);
      return true;
    } catch (e) {
      warnOnce("clear", "Failed to clear history: " + (e && e.message));
      return false;
    }
  }

  // ── Delta computation ─────────────────────────────────────

  function findClosest(observations, targetTime, toleranceMs) {
    if (!Array.isArray(observations) || !observations.length) return null;
    let best = null;
    let bestDist = Infinity;
    for (const o of observations) {
      if (!o || !Number.isFinite(o.observedAt)) continue;
      const dist = Math.abs(o.observedAt - targetTime);
      if (dist < bestDist) {
        bestDist = dist;
        best = o;
      }
    }
    if (bestDist > toleranceMs) return null;
    return best;
  }

  function deltaFor(current, past) {
    if (!Number.isFinite(current) || !Number.isFinite(past)) {
      return { absolute: null, percent: null };
    }
    const absolute = current - past;
    let percent = null;
    if (past > 0) {
      percent = (absolute / past) * 100;
    } else if (past === 0 && current === 0) {
      percent = 0;
    }
    return { absolute, percent };
  }

  function directionFor(percent) {
    if (!Number.isFinite(percent)) return "unknown";
    if (Math.abs(percent) < DIRECTION_THRESHOLD_PCT) return "stable";
    return percent > 0 ? "rising" : "falling";
  }

  function metricDelta(current, pastObservations, now, extract) {
    const result = { current: Number.isFinite(current) ? current : null };
    for (const [field, intervalMs] of Object.entries(INTERVALS)) {
      const target = now - intervalMs;
      const tolerance = intervalMs / 2;
      const match = findClosest(pastObservations, target, tolerance);
      const past = match ? extract(match) : null;
      const { absolute, percent } = deltaFor(
        Number.isFinite(current) ? current : null,
        past,
      );
      result[field] = {
        absolute,
        percent,
        direction: directionFor(percent),
      };
    }
    return result;
  }

  function trajectory(chainKey, address) {
    const observations = history(chainKey, address);
    // Fewer than two samples means there is nothing to compare. A
    // single observation is a snapshot, not a trajectory.
    if (observations.length < 2) return null;

    const current = observations[observations.length - 1];
    const past = observations.slice(0, -1);
    const now = current.observedAt;

    return {
      window: {
        from: observations[0].observedAt,
        to: now,
        sampleCount: observations.length,
      },
      concentration: {
        top10Pct: metricDelta(
          current.concentration?.top10Pct ?? null,
          past,
          now,
          (o) => o.concentration?.top10Pct ?? null,
        ),
      },
      liquidity: {
        usd: metricDelta(
          current.liquidity?.usd ?? null,
          past,
          now,
          (o) => o.liquidity?.usd ?? null,
        ),
      },
      holderCount: metricDelta(
        current.holderCount ?? null,
        past,
        now,
        (o) => o.holderCount ?? null,
      ),
      methodologyVersion: METHODOLOGY_VERSION,
      computedAt: Date.now(),
    };
  }

  return {
    record,
    history,
    trajectory,
    clear,
    METHODOLOGY_VERSION,
    // Exposed for tests only.
    _internal: {
      key,
      prune,
      findClosest,
      deltaFor,
      directionFor,
      INTERVALS,
      RETENTION_MS,
      MAX_OBSERVATIONS,
      DIRECTION_THRESHOLD_PCT,
    },
  };
})();

console.log("[Observations] Module loaded.");
// ---- js/lib/crypto/secure.js ----
// ===============================================================
//         Secure Encryption Module for Weaver Settings
// ===============================================================

const SecureCrypto = {
  CONFIG: {
    ITERATIONS: 600000,
    HASH: "SHA-256",
    KEY_LENGTH: 256,
    AES_ALGORITHM: "AES-GCM",
    IV_LENGTH: 12,
    SALT_LENGTH: 16,
  },

  async deriveKey(password, salt) {
    const enc = new TextEncoder();
    const keyMaterial = await crypto.subtle.importKey(
      "raw",
      enc.encode(password),
      "PBKDF2",
      false,
      ["deriveKey"],
    );
    return crypto.subtle.deriveKey(
      {
        name: "PBKDF2",
        salt,
        iterations: this.CONFIG.ITERATIONS,
        hash: this.CONFIG.HASH,
      },
      keyMaterial,
      { name: this.CONFIG.AES_ALGORITHM, length: this.CONFIG.KEY_LENGTH },
      false,
      ["encrypt", "decrypt"],
    );
  },

  async encrypt(plaintext, password) {
    if (!password || typeof password !== "string") {
      throw new Error("Password is required for encryption");
    }
    const salt = crypto.getRandomValues(
      new Uint8Array(this.CONFIG.SALT_LENGTH),
    );
    const iv = crypto.getRandomValues(new Uint8Array(this.CONFIG.IV_LENGTH));
    const key = await this.deriveKey(password, salt);
    const enc = new TextEncoder();
    const ciphertext = await crypto.subtle.encrypt(
      { name: this.CONFIG.AES_ALGORITHM, iv },
      key,
      enc.encode(plaintext),
    );
    return {
      ciphertext: Array.from(new Uint8Array(ciphertext)),
      iv: Array.from(iv),
      salt: Array.from(salt),
    };
  },

  async decrypt(encryptedObj, password) {
    if (!password || typeof password !== "string") {
      throw new Error("Password is required for decryption");
    }
    if (
      !encryptedObj ||
      !encryptedObj.ciphertext ||
      !encryptedObj.iv ||
      !encryptedObj.salt
    ) {
      throw new Error("Invalid encrypted object structure");
    }
    const salt = new Uint8Array(encryptedObj.salt);
    const iv = new Uint8Array(encryptedObj.iv);
    const ciphertext = new Uint8Array(encryptedObj.ciphertext);
    const key = await this.deriveKey(password, salt);
    try {
      const plaintext = await crypto.subtle.decrypt(
        { name: this.CONFIG.AES_ALGORITHM, iv },
        key,
        ciphertext,
      );
      return new TextDecoder().decode(plaintext);
    } catch (e) {
      throw new Error(
        "Decryption failed: incorrect password or corrupted data",
      );
    }
  },

  async encryptSettings(settings, password) {
    const sensitiveData = {
      ai: settings.ai || {},
      telegram: settings.telegram || {},
    };
    const plaintext = JSON.stringify(sensitiveData);
    return await this.encrypt(plaintext, password);
  },

  async decryptSettings(encryptedObj, password) {
    const plaintext = await this.decrypt(encryptedObj, password);
    return JSON.parse(plaintext);
  },
};

window.W = window.W || {};
W.crypto = W.crypto || {};
W.crypto.secure = SecureCrypto;

console.log("[SecureCrypto] Module loaded.");
// ---- js/lib/crypto/secure-session.js ----
// ================================================================
// Shared decrypted-settings cache
// ================================================================
// Problem this solves: encrypted_settings (AI key, Telegram token) is
// encrypted at rest via SecureCrypto, but more than one module needs to
// read the decrypted values during a session (the Settings page, and
// the Telegram sender for background alerts). Without a shared cache,
// each module either re-prompts for the passphrase constantly, or
// (as telegram.js used to) keeps its own plaintext copy on disk.
//
// This module holds the decrypted sensitive settings ONLY in memory,
// for the current page session. It is never written to localStorage.
// Reloading the page clears it — same as clicking "Lock Keys".
//
// The plaintext passphrase is captured by unlock()/saveWithPassphrase()
// and never leaves the module. Callers use save(sensitiveObj) which
// re-encrypts with the cached key — they never need to see or hold the
// passphrase themselves.

window.W = window.W || {};

W.secureSession = (() => {
  "use strict";

  let _passphrase = null;
  let _cache = null; // { ai: {...}, telegram: {...} } — decrypted, memory-only

  function isUnlocked() {
    return !!_cache;
  }

  function hasStoredSecrets() {
    return !!W.store.get("encrypted_settings", null);
  }

  async function unlock(passphrase) {
    if (typeof passphrase !== "string" || !passphrase) {
      throw new Error("Passphrase is required");
    }
    const blob = W.store.get("encrypted_settings", null);
    if (!blob) {
      throw new Error("No encrypted settings found");
    }
    const data = await W.crypto.secure.decryptSettings(blob, passphrase);
    _passphrase = passphrase;
    _cache = data;
    return data;
  }

  async function save(sensitiveObj) {
    if (!_passphrase) {
      throw new Error("Session is locked");
    }
    if (!sensitiveObj || typeof sensitiveObj !== "object") {
      throw new Error("save() requires a plain object");
    }
    const encrypted = await W.crypto.secure.encryptSettings(
      sensitiveObj,
      _passphrase,
    );
    W.store.set("encrypted_settings", encrypted);
    _cache = sensitiveObj;
  }

  async function saveWithPassphrase(sensitiveObj, passphrase) {
    if (typeof passphrase !== "string" || !passphrase) {
      throw new Error("Passphrase is required");
    }
    if (!sensitiveObj || typeof sensitiveObj !== "object") {
      throw new Error("saveWithPassphrase() requires a plain object");
    }
    const encrypted = await W.crypto.secure.encryptSettings(
      sensitiveObj,
      passphrase,
    );
    W.store.set("encrypted_settings", encrypted);
    _passphrase = passphrase;
    _cache = sensitiveObj;
  }

  function lock() {
    _passphrase = null;
    _cache = null;
  }

  function clear() {
    W.store.delete("encrypted_settings");
    _passphrase = null;
    _cache = null;
  }

  function get(key) {
    if (!_cache) return null;
    const v = _cache[key];
    if (v === null || v === undefined) return null;
    return typeof v === "object" ? { ...v } : v;
  }

  return Object.freeze({
    isUnlocked,
    hasStoredSecrets,
    unlock,
    save,
    saveWithPassphrase,
    lock,
    clear,
    get,
  });
})();

console.log("[SecureSession] Module loaded.");
// ---- js/lib/crypto/vault.js ----
// ================================================================
// Weaver Vault
// ================================================================
//
// Encrypted local storage for user-sensitive data. Implements the
// Session 1 audit design. See memory-bank/vault-audit-2026-10.md.
//
// Storage layout (raw localStorage keys, after W.store's "weaver:"):
//   vault::__root             { v, salt, verifier, writtenAt }
//   vault::<name>             { v, iv, ct, writtenAt }
//   vault::__staging::<name>  same shape as entries; migration only
//
// The `vault::` prefix is deliberately distinct from `vault_<code>`
// used by sync.js — no collision.
//
// Crypto:
//   PBKDF2-SHA256, 600k iterations, 256-bit → AES-GCM CryptoKey
//   16-byte salt, fixed per vault, stored in the root marker
//   Fresh 12-byte IV per write
//   Imported key is non-extractable, cached for the page session
//
// Session 1 decisions implemented:
//   1. Sibling W.vault (this file)
//   2. Locked reads throw VaultLockedError
//   3. lock() clears in-memory state, then location.reload()
//   4. No key persistence across refresh (re-prompt)
//   5. Migration uses staging key + raw localStorage read-back
//   6. exportBlob() returns ciphertext for sync.js
//   7. Derived CryptoKey cached for the page session

window.W = window.W || {};

W.vault = (() => {
  "use strict";

  const KDF_ITERATIONS = 600000;
  const KDF_HASH = "SHA-256";
  const KEY_LENGTH = 256;
  const AES = "AES-GCM";
  const IV_LENGTH = 12;
  const SALT_LENGTH = 16;
  const BLOB_V = 1;

  // Sentinel for "key not present". Cannot collide with any JSON
  // value because Symbols do not serialize. W.store.get(key,
  // undefined) would be silently replaced by the default parameter,
  // so we must pass a distinct sentinel.
  const MISSING = Symbol("vault-missing");

  // Canonical list of keys that route through the vault. W.store
  // consults this via routingFor(). Additions here are the ONLY place
  // to declare a new vault-routed key.
  const VAULT_KEYS = Object.freeze([
    // Key strings are the ACTUAL constants used by each module,
    // verified against the source. Do not infer from module names —
    // e.g. portfolio.js writes "portfolio_holdings", not "portfolio".
    "portfolio_holdings",     // portfolio.js:9  PORTFOLIO_KEY
    "portfolio_transactions", // portfolio.js:314 TX_KEY
    "watchlist",              // watchlist.js:8  KEY
    "investment_theses",      // theses.js:15   THESES_KEY
    "alerts_v2",              // alerts.js:11   KEY
    "token-unlocks",          // unlocks.js:12  KEY
    "learn",                  // learn.js:481   KEY
    "track_record",           // track-record.js:11 STORAGE_KEY
    "wallet_cost_basis",      // walletsync.js:61 BASIS_KEY
    "web3_state",             // web3.js (inline literal)
    "achievements",           // misc.js via W.miscStoreSet
    // Deliberately excluded:
    //   wallet_sync_data   — already encrypted by walletsync
    //   wallet_sync_cache  — sanitized cache, 5-min TTL
    //   gems.deployerHistory.v1 — public cache, rebuildable
    //   journal             — uses dynamic per-entry keys (Session 3c)
  ]);
  const VAULT_KEY_SET = new Set(VAULT_KEYS);

  const ROOT_KEY = "vault::__root";
  const ENTRY_PREFIX = "vault::";
  const STAGING_PREFIX = "vault::__staging::";
  const VERIFIER_PLAINTEXT = "weaver-vault-v1";
  const STORE_RAW_PREFIX = "weaver:";

  // Tests set globalThis.__WEAVER_VAULT_NO_RELOAD__ = true to make
  // lock() skip the page reload.
  function testMode() {
    return globalThis.__WEAVER_VAULT_NO_RELOAD__ === true;
  }

  class VaultLockedError extends Error {
    constructor(message) {
      super(message || "Vault is locked");
      this.name = "VaultLockedError";
      this.code = "VAULT_LOCKED";
    }
  }

  let _key = null;        // CryptoKey | null
  let _cache = null;      // { [name]: plaintext } | null
  let _unlocking = null;  // in-flight unlock, deduped

  function isLocked() { return _key === null; }
  function isUnlocked() { return _key !== null; }

  function hasStoredVault() {
    try { return W.store.get(ROOT_KEY, null) !== null; }
    catch { return false; }
  }

  // ── Base64 ────────────────────────────────────────────────
  function u8ToBase64(u8) {
    let s = "";
    for (let i = 0; i < u8.length; i++) s += String.fromCharCode(u8[i]);
    return btoa(s);
  }
  function base64ToU8(b64) {
    const s = atob(b64);
    const u8 = new Uint8Array(s.length);
    for (let i = 0; i < s.length; i++) u8[i] = s.charCodeAt(i);
    return u8;
  }

  // ── KDF ───────────────────────────────────────────────────
  async function deriveKey(passphrase, salt) {
    if (typeof passphrase !== "string" || !passphrase) {
      throw new Error("Passphrase is required");
    }
    const enc = new TextEncoder();
    const material = await crypto.subtle.importKey(
      "raw",
      enc.encode(passphrase),
      "PBKDF2",
      false,
      ["deriveKey"],
    );
    return crypto.subtle.deriveKey(
      {
        name: "PBKDF2",
        salt,
        iterations: KDF_ITERATIONS,
        hash: KDF_HASH,
      },
      material,
      { name: AES, length: KEY_LENGTH },
      false,
      ["encrypt", "decrypt"],
    );
  }

  // ── Encrypt / decrypt ─────────────────────────────────────
  async function encrypt(key, value) {
    const iv = crypto.getRandomValues(new Uint8Array(IV_LENGTH));
    const enc = new TextEncoder();
    const ct = await crypto.subtle.encrypt(
      { name: AES, iv },
      key,
      enc.encode(JSON.stringify(value)),
    );
    return { iv: u8ToBase64(iv), ct: u8ToBase64(new Uint8Array(ct)) };
  }

  async function decrypt(key, ivB64, ctB64) {
    const iv = base64ToU8(ivB64);
    const ct = base64ToU8(ctB64);
    const pt = await crypto.subtle.decrypt({ name: AES, iv }, key, ct);
    return JSON.parse(new TextDecoder().decode(pt));
  }

  // ── Raw read-back ─────────────────────────────────────────
  // storage.js swallows QuotaExceededError and falls back to an
  // in-memory map. That's invisible through W.store.get (which reads
  // the map). Direct localStorage is the only way to know whether a
  // write actually persisted.
  // Raw localStorage read/write that bypasses W.store's vault
  // routing. Migration must read the actual plaintext bytes — once
  // the vault is set up and unlocked, W.store.get(name) would route
  // to the vault cache and return fallback, not the plaintext.
  function rawGet(name) {
    try {
      const raw = localStorage.getItem(STORE_RAW_PREFIX + name);
      if (raw === null) return MISSING;
      return JSON.parse(raw);
    } catch {
      return MISSING;
    }
  }
  function rawSet(name, value) {
    localStorage.setItem(STORE_RAW_PREFIX + name, JSON.stringify(value));
  }

  function isPersisted(name) {
    try {
      return localStorage.getItem(STORE_RAW_PREFIX + name) !== null;
    } catch {
      return false;
    }
  }

  // ── Setup / unlock ────────────────────────────────────────
  async function setup(passphrase) {
    if (hasStoredVault()) {
      throw new Error("Vault already exists; use unlock()");
    }
    const salt = crypto.getRandomValues(new Uint8Array(SALT_LENGTH));
    const key = await deriveKey(passphrase, salt);
    const verifier = await encrypt(key, VERIFIER_PLAINTEXT);
    W.store.set(ROOT_KEY, {
      v: BLOB_V,
      salt: u8ToBase64(salt),
      verifier,
      writtenAt: Date.now(),
    });
    if (!isPersisted(ROOT_KEY)) {
      try { W.store.delete(ROOT_KEY); } catch (_) {}
      throw new Error(
        "Vault root could not be persisted (storage full?)",
      );
    }
    _key = key;
    _cache = Object.create(null);
  }

  async function unlock(passphrase) {
    if (_unlocking) return _unlocking;
    _unlocking = (async () => {
      const root = W.store.get(ROOT_KEY, null);
      if (!root || typeof root !== "object" || root.v !== BLOB_V) {
        throw new Error("No vault found");
      }
      const salt = base64ToU8(root.salt);
      const key = await deriveKey(passphrase, salt);
      let plain;
      try {
        plain = await decrypt(key, root.verifier.iv, root.verifier.ct);
      } catch {
        throw new Error(
          "Incorrect passphrase or corrupted vault (decryption failed)",
        );
      }
      if (plain !== VERIFIER_PLAINTEXT) {
        throw new Error("Incorrect passphrase (verifier mismatch)");
      }
      _key = key;
      _cache = Object.create(null);
      // Pre-decrypt every blob into the sync cache. Reads after
      // unlock are synchronous (getCached); this is where the cost
      // is paid, once.
      const existing = keys();
      for (const name of existing) {
        try {
          const blob = W.store.get(ENTRY_PREFIX + name, null);
          if (blob && blob.v === BLOB_V) {
            _cache[name] = await decrypt(_key, blob.iv, blob.ct);
          }
        } catch (e) {
          console.warn("[Vault] Failed to decrypt", name, e && e.message);
        }
      }
    })();
    try {
      await _unlocking;
    } finally {
      _unlocking = null;
    }
  }

  // ── Lock ──────────────────────────────────────────────────
  function lock() {
    _key = null;
    _cache = null;
    _unlocking = null;
    if (
      !testMode() &&
      typeof location !== "undefined" &&
      typeof location.reload === "function"
    ) {
      location.reload();
    }
  }

  // ── CRUD ──────────────────────────────────────────────────
  async function get(name) {
    if (isLocked()) throw new VaultLockedError();
    if (typeof name !== "string" || !name) {
      throw new Error("Vault key must be a non-empty string");
    }
    if (name in _cache) return _cache[name];
    const blob = W.store.get(ENTRY_PREFIX + name, null);
    if (!blob || blob.v !== BLOB_V) return null;
    const value = await decrypt(_key, blob.iv, blob.ct);
    _cache[name] = value;
    return value;
  }

  async function set(name, value) {
    if (isLocked()) throw new VaultLockedError();
    if (typeof name !== "string" || !name) {
      throw new Error("Vault key must be a non-empty string");
    }
    // Sync cache update first: reads immediately after set() see the
    // new value even before the async encryption completes.
    _cache[name] = value;
    const { iv, ct } = await encrypt(_key, value);
    const blob = { v: BLOB_V, iv, ct, writtenAt: Date.now() };
    W.store.set(ENTRY_PREFIX + name, blob);
    if (!isPersisted(ENTRY_PREFIX + name)) {
      throw new Error("Vault write did not persist (storage full?)");
    }
    _cache[name] = value;
  }

  async function del(name) {
    if (isLocked()) throw new VaultLockedError();
    W.store.delete(ENTRY_PREFIX + name);
    if (_cache) delete _cache[name];
  }

  function has(name) {
    return W.store.get(ENTRY_PREFIX + name, null) !== null;
  }

  function keys() {
    const out = [];
    const prefix = STORE_RAW_PREFIX + ENTRY_PREFIX;
    try {
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i);
        if (!k || !k.startsWith(prefix)) continue;
        const name = k.slice(prefix.length);
        if (name.startsWith("__")) continue;
        out.push(name);
      }
    } catch (_) {}
    return out;
  }

  // ── Migration ─────────────────────────────────────────────
  // Plaintext names live at W.store.get(name). Vault entries live at
  // W.store.get("vault::" + name). Migration:
  //   1. encrypt plaintext → staging key
  //   2. verify staging persisted via raw localStorage
  //   3. delete plaintext, verify gone
  //   4. write to vault key, verify persisted
  //   5. delete staging
  // Any verification failure aborts and leaves plaintext intact.
  async function migrateKeys(names) {
    if (isLocked()) throw new VaultLockedError();
    if (!Array.isArray(names)) throw new Error("names must be an array");

    const result = { migrated: [], skipped: [], failed: [] };

    for (const name of names) {
      if (typeof name !== "string" || !name || name.startsWith("__")) {
        result.skipped.push({ name, reason: "invalid-name" });
        continue;
      }
      if (W.store.get(ENTRY_PREFIX + name, null) !== null) {
        result.skipped.push({ name, reason: "vault-entry-exists" });
        continue;
      }
      const plain = rawGet(name);
      if (plain === MISSING) {
        result.skipped.push({ name, reason: "no-plaintext" });
        continue;
      }

      const stagingName = STAGING_PREFIX + name;
      let blob;
      try {
        const { iv, ct } = await encrypt(_key, plain);
        blob = { v: BLOB_V, iv, ct, writtenAt: Date.now() };
        W.store.set(stagingName, blob);
      } catch (e) {
        result.failed.push({
          name,
          reason: "encrypt-or-stage-failed",
          error: String(e && e.message ? e.message : e),
        });
        continue;
      }

      if (!isPersisted(stagingName)) {
        // W.store.set fell to _memory. Plaintext untouched.
        try { W.store.delete(stagingName); } catch (_) {}
        result.failed.push({ name, reason: "staging-not-persisted" });
        continue;
      }

      try { localStorage.removeItem(STORE_RAW_PREFIX + name); } catch (_) {}
      if (isPersisted(name)) {
        try { W.store.delete(stagingName); } catch (_) {}
        result.failed.push({ name, reason: "plaintext-delete-failed" });
        continue;
      }

      W.store.set(ENTRY_PREFIX + name, blob);
      if (!isPersisted(ENTRY_PREFIX + name)) {
        // Vault write failed. Restore plaintext from in-memory copy.
        try { rawSet(name, plain); } catch (_) {}
        try { W.store.delete(stagingName); } catch (_) {}
        result.failed.push({ name, reason: "vault-write-failed" });
        continue;
      }

      W.store.delete(stagingName);
      _cache[name] = plain;
      result.migrated.push(name);
    }

    return result;
  }

  // ── Sync read from cache ──────────────────────────────────
  // Throws when locked. Returns fallback if the key is not cached.
  // This is the sync read path that W.store routes vault keys to.
  // Synchronous read from the post-unlock cache. Returns fallback
  // when the vault is locked rather than throwing: the concat
  // bundle runs every module in one script, so an uncaught throw
  // at module-load time aborts every file that follows (including
  // app.js and its boot gate). Writes still throw when locked,
  // which is where the data-loss guard lives.
  function getCached(name, fallback) {
    if (isLocked()) return fallback === undefined ? null : fallback;
    if (_cache && name in _cache) return _cache[name];
    return fallback === undefined ? null : fallback;
  }

  // ── Routing decision for W.store ──────────────────────────
  // Returns "vault"    → W.store should call getCached / set / delete
  //         "locked"   → throw VaultLockedError (sensitive key, vault locked)
  //         "plaintext"→ no vault, or non-sensitive key: normal path
  // Returns "vault" or "plaintext". Never "locked": reads must
  // not throw at module load, and the write path is already
  // guarded by VaultLockedError inside W.vault.set/delete.
  function routingFor(key) {
    if (!VAULT_KEY_SET.has(key)) return "plaintext";
    if (!hasStoredVault()) return "plaintext";
    return "vault";
  }

  // ── Export ────────────────────────────────────────────────
  // Returns the raw ciphertext structure. sync.js calls this and
  // writes the result under vault_<syncCode>. No re-encryption.
  function exportBlob() {
    if (isLocked()) throw new VaultLockedError();
    const root = W.store.get(ROOT_KEY, null);
    const entries = {};
    for (const k of keys()) {
      entries[k] = W.store.get(ENTRY_PREFIX + k, null);
    }
    return { root, entries, exportedAt: Date.now() };
  }

  // ── Test hooks ────────────────────────────────────────────
  function __testClear() {
    _key = null;
    _cache = null;
    _unlocking = null;
  }
  function __testSetKey(key) {
    _key = key;
    _cache = Object.create(null);
  }

  return Object.freeze({
    isLocked,
    isUnlocked,
    hasStoredVault,
    setup,
    unlock,
    lock,
    get,
    set,
    delete: del,
    has,
    keys,
    migrateKeys,
    exportBlob,
    getCached,
    routingFor,
    VAULT_KEYS,
    VaultLockedError,
    __test: Object.freeze({
      clear: __testClear,
      setKey: __testSetKey,
    }),
  });
})();

console.log("[Vault] Module loaded.");
// ---- js/lib/sentry-init.js ----
// ===============================================================
//         Sentry Integration (Opt-In, Privacy-First)
// ===============================================================
// Constitution §2.6: no external transmission without explicit
// opt-in. This module does nothing unless the user enables error
// reporting in Settings AND provides a DSN.
//
// All events pass through W.logger.scrub before transmission.
// If scrubbing throws, the event is dropped rather than sent.
// ===============================================================

window.W = window.W || {};
W.sentry = (() => {
  let initialized = false;

  function isDntEnabled() {
    return (
      navigator.doNotTrack === "1" ||
      window.doNotTrack === "1" ||
      navigator.msDoNotTrack === "1"
    );
  }

  function beforeSend(event) {
    try {
      if (event.exception && event.exception.values) {
        for (const ex of event.exception.values) {
          if (ex.value) ex.value = W.logger.scrub(ex.value);
        }
      }
      if (event.breadcrumbs && event.breadcrumbs.values) {
        event.breadcrumbs.values = event.breadcrumbs.values.map((b) => ({
          ...b,
          message: b.message ? W.logger.scrub(b.message) : b.message,
          data: b.data ? W.logger.scrub(b.data) : b.data,
        }));
      }
      if (event.extra) event.extra = W.logger.scrub(event.extra);
      if (event.tags) event.tags = W.logger.scrub(event.tags);

      delete event.user;
      delete event.request;

      event.tags = event.tags || {};
      event.tags.weaver_version = "2.0";

      return event;
    } catch (e) {
      W.logger.warn("Sentry", "beforeSend scrubbing failed, dropping event");
      return null;
    }
  }

  async function init() {
    if (initialized) return false;

    const settings = W.store?.get("settings", {}) || {};
    const cfg = settings.sentry || {};

    if (!cfg.enabled) {
      W.logger.info("Sentry", "Not enabled by user, skipping init");
      return false;
    }

    if (!cfg.dsn || typeof cfg.dsn !== "string" || !/^https:\/\//.test(cfg.dsn)) {
      W.logger.warn("Sentry", "No valid DSN configured, skipping init");
      return false;
    }

    if (isDntEnabled()) {
      W.logger.info("Sentry", "Do Not Track is set, skipping init");
      return false;
    }

    if (typeof window.Sentry === "undefined") {
      W.logger.warn("Sentry", "SDK not loaded, skipping init");
      return false;
    }

    try {
      window.Sentry.init({
        dsn: cfg.dsn,
        environment: settings.environment || "production",
        release: "weaver@2.0.0",
        tracesSampleRate: 0.1,
        sendDefaultPii: false,
        beforeSend,
      });
      initialized = true;
      W.logger.info("Sentry", "Initialized with privacy-safe configuration");

      const buf = window.W.sentryBuffer || [];
      for (const entry of buf) {
        window.Sentry.captureMessage(entry.message, {
          level: entry.level,
          tags: { tag: entry.tag },
          extra: entry.data || {},
        });
      }
      window.W.sentryBuffer = [];
      return true;
    } catch (e) {
      W.logger.error("Sentry", "Initialization failed", e.message);
      return false;
    }
  }

  return { init, beforeSend, isInitialized: () => initialized };
})();

console.log("[Sentry] Privacy-safe observability module loaded.");
// ---- js/utils/format.js ----
// ===============================================================
//         Formatting Utilities for Weaver
// ===============================================================

// CRITICAL: Initialize W.fmt namespace FIRST
window.W = window.W || {};
W.fmt = W.fmt || {};

(function () {
  const CURRENCIES = {
    usd: { symbol: "$", locale: "en-US" },
    ngn: { symbol: "₦", locale: "en-NG" },
    eur: { symbol: "€", locale: "de-DE" },
    gbp: { symbol: "£", locale: "en-GB" },
    inr: { symbol: "₹", locale: "en-IN" },
    jpy: { symbol: "¥", locale: "ja-JP" },
    aud: { symbol: "A$", locale: "en-AU" },
    cad: { symbol: "C$", locale: "en-CA" },
    btc: { symbol: "₿", locale: "en-US" },
    eth: { symbol: "Ξ", locale: "en-US" },
  };

  /**
   * Format a number as currency
   */

  // -------------------------------------------------------------
  // FX rate state and helpers
  // -------------------------------------------------------------

  const FX_API = "https://api.frankfurter.dev/v2/rates";
  const FX_TTL_MS = 6 * 60 * 60 * 1000;

  let fxRates = { USD: 1 };
  let fxDate = null;
  let fxLoadedAt = 0;
  let fxLoading = null;

  W.fmt.getCurrency = function () {
    try {
      const settings = W.store?.get?.("settings", {});
      if (
        settings &&
        typeof settings === "object" &&
        !Array.isArray(settings) &&
        typeof settings.currency === "string"
      ) {
        const currency = settings.currency.toLowerCase();
        if (CURRENCIES[currency]) {
          return currency;
        }
      }
    } catch (e) {
      console.warn("[Format] Failed to read currency:", e?.message);
    }
    return "usd";
  };

  W.fmt.getCurrencyConfig = function () {
    const currency = W.fmt.getCurrency();
    return { ...(CURRENCIES[currency] || CURRENCIES.usd) };
  };

  W.fmt.getFxState = function () {
    return {
      rates: { ...fxRates },
      date: fxDate,
      loadedAt: fxLoadedAt,
      stale: !fxLoadedAt || Date.now() - fxLoadedAt > FX_TTL_MS,
    };
  };

  W.fmt.loadFxRates = async function (options = {}) {
    const force = options.force === true;
    if (!force && fxLoadedAt && Date.now() - fxLoadedAt < FX_TTL_MS) {
      return W.fmt.getFxState();
    }
    if (fxLoading) {
      return fxLoading;
    }
    fxLoading = (async () => {
      try {
        const targets = ["EUR", "GBP", "NGN", "INR", "JPY", "AUD", "CAD"].join(
          ",",
        );
        const url = `${FX_API}?base=USD&quotes=${encodeURIComponent(targets)}`;
        const fxController = new AbortController();
        const fxTimer = setTimeout(() => fxController.abort(), 10000);
        let response;
        try {
          response = await fetch(url, {
            method: "GET",
            headers: { Accept: "application/json" },
            credentials: "omit",
            cache: "no-store",
            signal: fxController.signal,
          });
        } finally {
          clearTimeout(fxTimer);
        }
        if (!response.ok) {
          throw new Error(`FX provider returned HTTP ${response.status}`);
        }
        const payload = await response.json();
        if (!Array.isArray(payload)) {
          throw new Error("FX provider returned invalid data");
        }
        const nextRates = { USD: 1 };
        for (const row of payload) {
          if (
            !row ||
            typeof row.quote !== "string" ||
            typeof row.rate !== "number" ||
            !Number.isFinite(row.rate) ||
            row.rate <= 0
          ) {
            continue;
          }
          const code = row.quote.toUpperCase();
          if (CURRENCIES[code.toLowerCase()]) {
            nextRates[code] = row.rate;
          }
        }
        if (Object.keys(nextRates).length < 2) {
          throw new Error("FX provider returned no usable rates");
        }
        fxRates = nextRates;
        const firstDate = payload.find(
          (row) => typeof row?.date === "string",
        );
        fxDate = firstDate?.date || null;
        fxLoadedAt = Date.now();
        console.info(
          `[Format] FX rates loaded${fxDate ? ` for ${fxDate}` : ""}.`,
        );
        return W.fmt.getFxState();
      } catch (error) {
        console.warn(
          "[Format] FX rate loading failed:",
          error?.message || error,
        );
        return W.fmt.getFxState();
      } finally {
        fxLoading = null;
      }
    })();
    return fxLoading;
  };

  W.fmt.refreshFxRates = function () {
    return W.fmt.loadFxRates({ force: true });
  };

  W.fmt.money = function (amount, options = {}) {
    if (amount === null || amount === undefined || isNaN(amount)) {
      return "$0.00";
    }
    const numericAmount = Number(amount);
    if (!Number.isFinite(numericAmount)) {
      return "$0.00";
    }
    const currency = W.fmt.getCurrency();
    const config = CURRENCIES[currency] || CURRENCIES.usd;
    const code = currency.toUpperCase();
    let convertedAmount = numericAmount;
    // BTC and ETH are not fiat. Do not convert via FX rates.
    if (code !== "USD" && code !== "BTC" && code !== "ETH") {
      const rate = fxRates[code];
      if (Number.isFinite(rate) && rate > 0) {
        convertedAmount = numericAmount * rate;
      }
    }
    try {
      return new Intl.NumberFormat(config.locale, {
        style: "currency",
        currency: code,
        minimumFractionDigits: options.compact ? 0 : 2,
        maximumFractionDigits: options.compact ? 0 : 2,
      }).format(convertedAmount);
    } catch (e) {
      return `${config.symbol}${convertedAmount.toFixed(2)}`;
    }
  };

  /**
   * Format a number as price (crypto)
   */
  W.fmt.price = function (price) {
    if (price === null || price === undefined || isNaN(price)) return "$0.00";
    if (price < 0.01) return `$${price.toFixed(6)}`;
    if (price < 1) return `$${price.toFixed(4)}`;
    return `$${price.toFixed(2)}`;
  };

  /**
   * Format percentage
   */
  W.fmt.pct = function (value, decimals = 2) {
    if (value === null || value === undefined || isNaN(value)) return "0.00%";
    const sign = value >= 0 ? "+" : "";
    return `${sign}${value.toFixed(decimals)}%`;
  };

  /**
   * Format compact numbers (1.2M, 3.4B)
   */
  W.fmt.compact = function (num) {
    if (num === null || num === undefined || isNaN(num)) return "0";
    if (num >= 1e12) return `${(num / 1e12).toFixed(2)}T`;
    if (num >= 1e9) return `${(num / 1e9).toFixed(2)}B`;
    if (num >= 1e6) return `${(num / 1e6).toFixed(2)}M`;
    if (num >= 1e3) return `${(num / 1e3).toFixed(2)}K`;
    return num.toFixed(2);
  };

    W.fmt.num = function (n) {
      if (n == null || isNaN(n)) return "—";
      const num = Number(n);
      const abs = Math.abs(num);
      if (abs >= 1e12) return `${(num / 1e12).toFixed(2)}T`;
      if (abs >= 1e9) return `${(num / 1e9).toFixed(2)}B`;
      if (abs >= 1e6) return `${(num / 1e6).toFixed(2)}M`;
      if (abs >= 1e3) return `${(num / 1e3).toFixed(2)}K`;
      return num.toLocaleString("en-US", { maximumFractionDigits: 2 });
    };

  /**
   * Get currency symbol
   */
  W.fmt.getSymbol = function () {
    const currency = W.store?.get("settings", {})?.currency || "usd";
    return CURRENCIES[currency]?.symbol || "$";
  };

  /**
   * Escape HTML to prevent XSS
   */
  W.fmt.escapeHTML = function (str) {
    // Escapes &, <, >, ", '. Attribute-safe: the output can be used
    // in text and quoted-attribute positions.
    //
    // The prior implementation used the textContent → innerHTML
    // trick, which escapes only &, <, > — unsafe in any attribute
    // context where a payload containing a quote could break out.
    if (str === null || str === undefined) return "";
    let value;
    try {
      value = String(str);
    } catch (e) {
      return "";
    }
    return value.replace(/[&<>"']/g, (char) => {
      switch (char) {
        case "&":
          return "&amp;";
        case "<":
          return "&lt;";
        case ">":
          return "&gt;";
        case '"':
          return "&quot;";
        case "'":
          return "&#39;";
        default:
          return char;
      }
    });
  };

  /**
   * Format timestamp to readable date
   */
  W.fmt.date = function (timestamp, options = {}) {
    if (!timestamp) return "N/A";
    const date = new Date(timestamp);
    if (options.short) {
      return date.toLocaleDateString();
    }
    return date.toLocaleString();
  };

  /**
   * Format relative time (e.g., "5 minutes ago")
   */
  W.fmt.relativeTime = function (timestamp) {
    if (!timestamp) return "N/A";
    const seconds = Math.floor((Date.now() - new Date(timestamp)) / 1000);

    if (seconds < 60) return "just now";
    if (seconds < 3600) return `${Math.floor(seconds / 60)}m ago`;
    if (seconds < 86400) return `${Math.floor(seconds / 3600)}h ago`;
    if (seconds < 604800) return `${Math.floor(seconds / 86400)}d ago`;
    return W.fmt.date(timestamp, { short: true });
  };

  /**
   * Mask a wallet address for privacy.
   * e.g., "0x1234567890abcdef1234567890abcdef12345678" -> "0x1234...5678"
   */
  W.fmt.maskAddress = function (address) {
    if (!address || typeof address !== "string") return "";
    if (address.length <= 10) return address;
    return `${address.substring(0, 6)}…${address.substring(address.length - 4)}`;
  };

  console.log("[Format] Utilities loaded.");

  // ── Boot: load FX rates once the page is interactive ──────────
  // The prior hook lived inside W.applySettings in app.js, which is
  // defined but never called — so FX rates were never fetched at
  // boot, and every currency switch showed the USD number with a
  // different symbol. This block self-boots: it kicks off the load
  // on DOM ready (or immediately if readyState is already past
  // loading), then triggers a re-render if W.refresh is available
  // and the rates actually arrived.
  function bootFx() {
    const before = W.fmt.getFxState();
    W.fmt
      .loadFxRates()
      .then(() => {
        const after = W.fmt.getFxState();
        if (after && before && after.loadedAt !== before.loadedAt) {
          try {
            if (typeof W.refresh === "function") W.refresh();
          } catch (e) {
            console.warn("[Format] FX re-render failed:", e?.message || e);
          }
        }
      })
      .catch((e) => {
        console.warn("[Format] FX boot load failed:", e?.message || e);
      });
  }

  if (typeof document !== "undefined") {
    if (document.readyState === "loading") {
      document.addEventListener("DOMContentLoaded", bootFx, { once: true });
    } else {
      // Deferred one tick so app.js can finish defining W.refresh.
      setTimeout(bootFx, 0);
    }
  }
})();
// ---- js/utils/finance.js ----
// ===============================================================
//         Deterministic Financial Math Engine for Weaver
// ===============================================================
//
// Purpose: Provide 100% deterministic, edge-case-safe financial
//          calculations. Never use LLMs for these operations.
//
// Rules:
//   - Never return NaN or Infinity.
//   - Handle missing/null/zero values gracefully.
//   - All arithmetic is strictly deterministic.
//
// ===============================================================

window.W = window.W || {};

W.finance = (() => {
  /**
   * Safely parse a number. Returns 0 if NaN/null/undefined.
   */
  function safeNumber(val) {
    if (val === null || val === undefined || val === "") return 0;
    const num = parseFloat(val);
    return isNaN(num) ? 0 : num;
  }

  /**
   * Calculate total value (Amount * Price).
   */
  function calculateValue(amount, price) {
    return safeNumber(amount) * safeNumber(price);
  }

  /**
   * Calculate Profit/Loss (Value - Cost).
   */
  function calculatePL(value, cost) {
    return safeNumber(value) - safeNumber(cost);
  }

  /**
   * Calculate Profit/Loss Percentage.
   * Safely handles division by zero (returns 0 instead of Infinity/NaN).
   */
  function calculatePLPercent(pl, cost) {
    const safeCost = safeNumber(cost);
    if (safeCost === 0) return 0;
    return (safeNumber(pl) / safeCost) * 100;
  }

  /**
   * Calculate portfolio allocation percentage.
   * Safely handles division by zero.
   */
  function calculateAllocation(assetValue, totalValue) {
    const safeTotal = safeNumber(totalValue);
    if (safeTotal === 0) return 0;
    return (safeNumber(assetValue) / safeTotal) * 100;
  }

  /**
   * Calculate total portfolio metrics from an array of holdings.
   * Each holding must have: { amount, price, cost }
   *
   * FIXED: Added proper validation and error handling.
   */
  function calculatePortfolioTotals(holdings) {
    // Validate input
    if (!Array.isArray(holdings)) {
      console.warn(
        "[Finance] calculatePortfolioTotals: holdings is not an array",
      );
      return { totalValue: 0, totalCost: 0, totalPL: 0, totalPLPercent: 0 };
    }

    if (holdings.length === 0) {
      return { totalValue: 0, totalCost: 0, totalPL: 0, totalPLPercent: 0 };
    }

    let totalValue = 0;
    let totalCost = 0;
    let invalidCount = 0;

    holdings.forEach((h, index) => {
      // Skip invalid holdings
      if (!h || typeof h !== "object") {
        invalidCount++;
        return;
      }

      const amount = safeNumber(h.amount);
      const price = safeNumber(h.price);
      const cost = safeNumber(h.cost);

      // Validate: cost should be >= 0
      if (cost < 0) {
        console.warn(
          `[Finance] Negative cost for ${h.symbol || "holding #" + index}, using 0`,
        );
        // Use amount * price as fallback cost
        const fallbackCost = amount * price;
        totalValue += amount * price;
        totalCost += fallbackCost;
        return;
      }

      // Validate: amount should be >= 0
      if (amount < 0) {
        console.warn(
          `[Finance] Negative amount for ${h.symbol || "holding #" + index}, using 0`,
        );
        return;
      }

      // Validate: price should be >= 0
      if (price < 0) {
        console.warn(
          `[Finance] Negative price for ${h.symbol || "holding #" + index}, using 0`,
        );
        return;
      }

      totalValue += amount * price;
      totalCost += cost;
    });

    if (invalidCount > 0) {
      console.warn(`[Finance] Skipped ${invalidCount} invalid holdings`);
    }

    const totalPL = calculatePL(totalValue, totalCost);
    const totalPLPercent = calculatePLPercent(totalPL, totalCost);

    return {
      totalValue: Math.round(totalValue * 100) / 100, // Round to 2 decimals
      totalCost: Math.round(totalCost * 100) / 100,
      totalPL: Math.round(totalPL * 100) / 100,
      totalPLPercent: Math.round(totalPLPercent * 100) / 100,
    };
  }

  /**
   * Calculate weighted average price for an asset.
   * Useful for cost basis tracking with multiple buys.
   */
  function calculateWeightedAverage(holdings, symbol) {
    const filtered = holdings.filter(
      (h) => h.symbol?.toUpperCase() === symbol?.toUpperCase(),
    );
    if (!filtered.length) return 0;

    let totalCost = 0;
    let totalAmount = 0;

    filtered.forEach((h) => {
      const amount = safeNumber(h.amount);
      const cost = safeNumber(h.cost);
      totalCost += cost;
      totalAmount += amount;
    });

    if (totalAmount === 0) return 0;
    return totalCost / totalAmount;
  }

  /**
   * Calculate the Sharpe-like ratio for a portfolio.
   * Simplified: (Return - Risk-Free) / Volatility
   */
  function calculateRiskAdjustedReturn(returns, riskFreeRate = 0.02) {
    if (!Array.isArray(returns) || returns.length < 2) return 0;

    const avgReturn = returns.reduce((a, b) => a + b, 0) / returns.length;
    const variance =
      returns.reduce((a, b) => a + Math.pow(b - avgReturn, 2), 0) /
      returns.length;
    const volatility = Math.sqrt(variance);

    if (volatility === 0) return 0;
    return (avgReturn - riskFreeRate) / volatility;
  }

  return {
    safeNumber,
    calculateValue,
    calculatePL,
    calculatePLPercent,
    calculateAllocation,
    calculatePortfolioTotals,
    calculateWeightedAverage,
    calculateRiskAdjustedReturn,
  };
})();

console.log("[Finance] Deterministic math engine loaded.");
// ---- js/utils/debounce.js ----
//  Debounce Utility

window.W = window.W || {};

/**
 * Debounce a function – limits how often it can be called.
 *
 * @param {Function} fn - The function to debounce
 * @param {number} ms - Delay in milliseconds (default: 300)
 * @param {boolean} immediate - If true, call on leading edge instead of trailing
 * @returns {Function} Debounced function
 *
 * @example
 * const search = W.debounce(async (query) => {
 *   const results = await api.search(query);
 *   render(results);
 * }, 350);
 *
 * input.addEventListener('input', (e) => search(e.target.value));
 */
W.debounce = function (fn, ms = 300, immediate = false) {
  // Validate inputs
  if (typeof fn !== "function") {
    console.warn("[Debounce] Expected a function, got", typeof fn);
    return () => {};
  }
  if (typeof ms !== "number" || ms < 0) {
    console.warn("[Debounce] Invalid delay, using 300ms");
    ms = 300;
  }

  let timer = null;
  let lastCall = 0;

  return function (...args) {
    const context = this;
    const now = Date.now();

    // If immediate and timer is not set, call immediately
    if (immediate && timer === null) {
      fn.apply(context, args);
      timer = setTimeout(() => {
        timer = null;
      }, ms);
      return;
    }

    // Clear the previous timer
    if (timer !== null) {
      clearTimeout(timer);
      timer = null;
    }

    // Set a new timer
    timer = setTimeout(() => {
      timer = null;
      // Only call if enough time has passed (for trailing edge)
      if (!immediate || now - lastCall >= ms) {
        fn.apply(context, args);
        lastCall = now;
      }
    }, ms);
  };
};

/**
 * Throttle a function – ensures it's called at most once per interval.
 *
 * @param {Function} fn - The function to throttle
 * @param {number} ms - Minimum time between calls (default: 300)
 * @returns {Function} Throttled function
 *
 * @example
 * const update = W.throttle(() => renderChart(), 1000);
 * window.addEventListener('resize', update);
 */
W.throttle = function (fn, ms = 300) {
  if (typeof fn !== "function") {
    console.warn("[Throttle] Expected a function, got", typeof fn);
    return () => {};
  }

  let timer = null;
  let lastCall = 0;

  return function (...args) {
    const context = this;
    const now = Date.now();

    if (timer !== null) {
      // Already scheduled
      return;
    }

    const remaining = ms - (now - lastCall);
    if (remaining <= 0) {
      // Enough time has passed – call immediately
      fn.apply(context, args);
      lastCall = now;
    } else {
      // Schedule for later
      timer = setTimeout(() => {
        timer = null;
        lastCall = Date.now();
        fn.apply(context, args);
      }, remaining);
    }
  };
};

/**
 * Leading-edge throttle – calls immediately, then ignores subsequent calls
 * until the interval has passed.
 *
 * @param {Function} fn - The function to throttle
 * @param {number} ms - Minimum time between calls (default: 300)
 * @returns {Function} Throttled function (leading edge)
 */
W.throttleLeading = function (fn, ms = 300) {
  if (typeof fn !== "function") {
    console.warn("[ThrottleLeading] Expected a function, got", typeof fn);
    return () => {};
  }

  let lastCall = 0;

  return function (...args) {
    const context = this;
    const now = Date.now();

    if (now - lastCall >= ms) {
      lastCall = now;
      fn.apply(context, args);
    }
  };
};

console.log("[Utils] Debounce module loaded.");
// ---- js/utils/logger.js ----
// ===============================================================
//         Weaver Logger
// ===============================================================
// Structured logging with automatic PII scrubbing.
// Constitution §2.6: never log wallet addresses, API keys, seeds.
//
// Public API:
//   W.logger.error/warn/info/debug/trace(msg, data)
//   W.logger.setLevel("error"|"warn"|"info"|"debug"|"trace")
//   W.logger.scrub(value)         — for direct use and testing
//   W.logger.setEnabled(bool)
// ===============================================================

window.W = window.W || {};

(function () {
  const LOG_LEVELS = { error: 0, warn: 1, info: 2, debug: 3, trace: 4 };
  const DEFAULT_LEVEL = "info";

  let currentLevel = (() => {
    const saved = (() => {
      try {
        return localStorage.getItem("weaver_log_level");
      } catch {
        return null;
      }
    })();
    return LOG_LEVELS[saved] !== undefined ? LOG_LEVELS[saved] : LOG_LEVELS[DEFAULT_LEVEL];
  })();

  let enabled = true;

  // ── PII scrubbing ─────────────────────────────────────────
  // Order matters. Wallet patterns are masked first because their
  // shape would otherwise match the generic API-key rule.
  function scrub(value) {
    if (value === null || value === undefined) return value;

    if (typeof value !== "string") {
      const seen = new WeakSet();
      const walk = (v) => {
        if (v === null || typeof v !== "object") {
          return typeof v === "string" ? scrub(v) : v;
        }
        if (seen.has(v)) return "[Circular]";
        seen.add(v);
        if (Array.isArray(v)) return v.map(walk);
        const out = {};
        for (const k of Object.keys(v)) {
          if (/^(token|key|secret|password|passphrase|dsn|seed)$/i.test(k)) {
            out[k] = "[REDACTED]";
          } else {
            out[k] = walk(v[k]);
          }
        }
        return out;
      };
      try {
        return walk(value);
      } catch {
        return "[unserializable]";
      }
    }

    let s = value;

    // 1. EVM addresses: 0x + 40 hex chars
    s = s.replace(/\b0x[a-fA-F0-9]{40}\b/g, (m) =>
      W.fmt?.maskAddress ? W.fmt.maskAddress(m) : m.slice(0, 6) + "…" + m.slice(-4),
    );

    // 2. Solana base58 addresses: 32–44 chars, no 0/O/I/l
    s = s.replace(/\b[1-9A-HJ-NP-Za-km-z]{32,44}\b/g, (m) =>
      m.slice(0, 6) + "…" + m.slice(-4),
    );

    // 3. Telegram bot tokens: <digits>:<35 chars>
    s = s.replace(/\b\d{8,12}:[A-Za-z0-9_-]{35}\b/g, "[REDACTED_TG_TOKEN]");

    // 4. Sentry DSNs
    s = s.replace(/https:\/\/[a-f0-9]{32}@[^\s]+/gi, "[REDACTED_DSN]");

    // 5. OpenAI/Anthropic/Stripe-style keys
    s = s.replace(/\bsk-[A-Za-z0-9_-]{20,}\b/g, "[REDACTED_KEY]");
    s = s.replace(/\bsk_live_[A-Za-z0-9]{20,}\b/g, "[REDACTED_KEY]");
    s = s.replace(/\bsk_test_[A-Za-z0-9]{20,}\b/g, "[REDACTED_KEY]");

    // 6. Seed phrases: 12+ lowercase words separated by spaces
    s = s.replace(/\b([a-z]{3,8}\s+){11,23}[a-z]{3,8}\b/g, "[REDACTED_SEED]");

    return s;
  }

  // ── Core log function ─────────────────────────────────────
  function log(level, tag, msg, data) {
    if (!enabled) return;
    if (LOG_LEVELS[level] > currentLevel) return;

    const prefix = "[" + new Date().toISOString() + "] [" + level.toUpperCase() + "] [" + tag + "]";
    const cleanMsg = scrub(msg);
    const cleanData = data !== undefined ? scrub(data) : undefined;

    const fn =
      level === "error"
        ? console.error
        : level === "warn"
          ? console.warn
          : level === "debug" || level === "trace"
            ? console.debug
            : console.log;

    if (cleanData !== undefined) {
      fn(prefix, cleanMsg, cleanData);
    } else {
      fn(prefix, cleanMsg);
    }

    if (level === "error" && window.W.sentryBuffer) {
      window.W.sentryBuffer.push({
        timestamp: new Date().toISOString(),
        level,
        tag,
        message: cleanMsg,
        data: cleanData,
      });
      if (window.W.sentryBuffer.length > 50) window.W.sentryBuffer.shift();
    }
  }

  W.logger = {
    error: (tag, msg, data) => log("error", tag, msg, data),
    warn: (tag, msg, data) => log("warn", tag, msg, data),
    info: (tag, msg, data) => log("info", tag, msg, data),
    debug: (tag, msg, data) => log("debug", tag, msg, data),
    trace: (tag, msg, data) => log("trace", tag, msg, data),
    setLevel: (level) => {
      if (LOG_LEVELS[level] === undefined) return;
      currentLevel = LOG_LEVELS[level];
      try {
        localStorage.setItem("weaver_log_level", level);
      } catch {
        /* ignore quota errors */
      }
    },
    setEnabled: (v) => {
      enabled = !!v;
    },
    scrub,
  };
})();

window.W.sentryBuffer = window.W.sentryBuffer || [];

console.log("[Logger] Module loaded.");
