// ---- js/ui/ui.js ----
// ================================================================
//  Weaver UI Utilities
// ================================================================

window.W = window.W || {};

W.ui = {
  /**
   * Show a toast notification
   */
  toast(msg, type = "info", ms = 3500) {
    const container = document.getElementById("toasts");
    if (!container) {
      console.warn("[UI] Toast container not found");
      return;
    }
    const el = document.createElement("div");
    el.className = `toast ${type}`;
    el.innerHTML = msg;
    container.appendChild(el);
    setTimeout(() => {
      el.classList.add("hide");
      setTimeout(() => el.remove(), 300);
    }, ms);
  },

  /**
   * Create a modal dialog
   */
  modal({ title, body, footer }) {
    const root = document.getElementById("modal-root");
    if (!root) {
      console.warn("[UI] Modal root not found");
      return { close: () => {}, el: null };
    }

    root.innerHTML = `
      <div class="modal-backdrop" id="modal-backdrop">
        <div class="modal">
          <div class="modal-head">
            <h3>${title}</h3>
            <button class="modal-x" aria-label="Close">✕</button>
          </div>
          <div class="modal-body">${body}</div>
          ${footer ? `<div class="modal-foot">${footer}</div>` : ""}
        </div>
      </div>
    `;

    function escHandler(e) {
      if (e.key === "Escape") close();
    }
    function close() {
      root.innerHTML = "";
      document.removeEventListener("keydown", escHandler);
    }

    const closeBtn = root.querySelector(".modal-x");
    if (closeBtn) closeBtn.onclick = close;

    const backdrop = root.querySelector("#modal-backdrop");
    if (backdrop) {
      backdrop.addEventListener("click", (e) => {
        if (e.target.id === "modal-backdrop") close();
      });
    }

    document.addEventListener("keydown", escHandler);

    return {
      close,
      el: root.querySelector(".modal"),
    };
  },

  /**
   * Masked password-entry modal.
   */
  promptPassword({
    title = "Enter Password",
    message = "",
    confirmLabel = "Continue",
    minLength = 0,
    placeholder = "Password",
  } = {}) {
    return new Promise((resolve) => {
      const esc =
        W.fmt && typeof W.fmt.escapeHTML === "function"
          ? W.fmt.escapeHTML
          : (s) =>
              String(s == null ? "" : s).replace(
                /[&<>"']/g,
                (c) =>
                  ({
                    "&": "&amp;",
                    "<": "&lt;",
                    ">": "&gt;",
                    '"': "&quot;",
                    "'": "&#39;",
                  })[c],
              );
      const body = `
        ${message ? `<p class="muted small">${esc(message)}</p>` : ""}
        <label>
          <input type="password" id="pw-modal-input" placeholder="${esc(placeholder)}" autocomplete="off" class="w-100">
        </label>
        <p id="pw-modal-error" class="down small hidden"></p>
      `;
      const footer = `
        <button class="btn ghost" data-a="cancel">Cancel</button>
        <button class="btn primary" data-a="ok">${esc(confirmLabel)}</button>
      `;

      const m = this.modal({ title, body, footer });
      if (!m.el) {
        resolve(null);
        return;
      }

      const input = m.el.querySelector("#pw-modal-input");
      const errorEl = m.el.querySelector("#pw-modal-error");
      const cancelBtn = m.el.querySelector('[data-a="cancel"]');
      const okBtn = m.el.querySelector('[data-a="ok"]');
      const backdrop = document.getElementById("modal-backdrop");
      const closeBtn = m.el.querySelector(".modal-x");

      let settled = false;
      function escHandler(e) {
        if (e.key === "Escape") finish(null);
      }
      function finish(value) {
        if (settled) return;
        settled = true;
        document.removeEventListener("keydown", escHandler);
        m.close();
        resolve(value);
      }

      const submit = () => {
        const val = input.value;
        if (minLength && val.length < minLength) {
          errorEl.textContent =
            val.length === 0
              ? "This field is required."
              : `Must be at least ${minLength} characters.`;
          errorEl.classList.remove("hidden");
          input.focus();
          return;
        }
        finish(val);
      };

      cancelBtn.onclick = () => finish(null);
      okBtn.onclick = submit;
      input.addEventListener("keydown", (e) => {
        if (e.key === "Enter") {
          e.preventDefault();
          submit();
        }
      });

      if (closeBtn) closeBtn.addEventListener("click", () => finish(null));
      if (backdrop) {
        backdrop.addEventListener("click", (e) => {
          if (e.target.id === "modal-backdrop") finish(null);
        });
      }
      document.addEventListener("keydown", escHandler);

      setTimeout(() => input?.focus(), 30);
    });
  },

  /**
   * Show a confirmation dialog
   */
  confirm(msg, onYes) {
    const m = this.modal({
      title: "Are you sure?",
      body: `<p>${msg}</p>`,
      footer: `
        <button class="btn ghost" data-a="no">Cancel</button>
        <button class="btn danger" data-a="yes">Delete</button>
      `,
    });

    const noBtn = m.el?.querySelector('[data-a="no"]');
    const yesBtn = m.el?.querySelector('[data-a="yes"]');

    if (noBtn) noBtn.onclick = m.close;
    if (yesBtn) {
      yesBtn.onclick = () => {
        m.close();
        onYes();
      };
    }
  },

  /**
   * Search-as-you-type coin picker
   */
  coinPicker(container, onPick) {
    if (!container) {
      console.warn("[UI] coinPicker: container not found");
      return;
    }

    const esc =
      W.fmt && typeof W.fmt.escapeHTML === "function"
        ? W.fmt.escapeHTML
        : (v) =>
            String(v == null ? "" : v).replace(/[&<>"']/g, (c) =>
              ({
                "&": "&amp;",
                "<": "&lt;",
                ">": "&gt;",
                '"': "&quot;",
                "'": "&#39;",
              })[c],
            );

    container.innerHTML = `
      <div class="picker">
        <input class="picker-input" placeholder="Search coin (e.g. bitcoin, ETH)…" autocomplete="off">
        <div class="picker-results hidden"></div>
        <div class="picker-chip hidden"></div>
      </div>
    `;

    const input = container.querySelector(".picker-input");
    const results = container.querySelector(".picker-results");
    const chip = container.querySelector(".picker-chip");

    if (!input || !results || !chip) return;

    const doSearch = W.debounce
      ? W.debounce(async () => {
          const q = input.value.trim();
          if (q.length < 2) {
            results.classList.add("hidden");
            return;
          }

          try {
            if (!W.api || !W.api.search) {
              throw new Error("CoinGecko API not loaded");
            }
            const data = await W.api.search(q);
            const coins = (data.coins || []).slice(0, 8);

            if (!coins.length) {
              results.innerHTML =
                '<div class="picker-item muted">No results</div>';
              results.classList.remove("hidden");
              return;
            }

            results.innerHTML = coins
              .map((c) => {
                const id = esc(String(c.id ?? ""));
                const symbol = esc(String(c.symbol ?? "").toUpperCase());
                const name = esc(String(c.name ?? ""));
                const thumb = esc(String(c.thumb ?? ""));
                const rank = Number.isFinite(Number(c.market_cap_rank))
                  ? esc(String(c.market_cap_rank))
                  : "";
                return `
              <div class="picker-item" data-id="${id}" data-symbol="${symbol}" data-name="${name}" data-img="${thumb}">
                <img src="${thumb}" alt="">
                <span>${name} <b class="muted">${symbol}</b></span>
                ${rank ? `<span class="muted small">#${rank}</span>` : ""}
              </div>
            `;
              })
              .join("");

            results.classList.remove("hidden");

            results.querySelectorAll(".picker-item[data-id]").forEach((it) => {
              it.onclick = () => {
                const pick = {
                  id: it.dataset.id,
                  symbol: it.dataset.symbol,
                  name: it.dataset.name,
                  img: it.dataset.img,
                };
                chip.innerHTML = `
              <img src="${esc(String(pick.img ?? ""))}" alt="">
              ${esc(String(pick.name ?? ""))} (${esc(String(pick.symbol ?? "").toUpperCase())})
              <button class="picker-clear">✕</button>
            `;
                chip.classList.remove("hidden");
                input.classList.add("hidden");
                results.classList.add("hidden");
                chip.querySelector(".picker-clear").onclick = () => {
                  chip.classList.add("hidden");
                  input.classList.remove("hidden");
                  input.value = "";
                  onPick(null);
                };
                onPick(pick);
              };
            });
          } catch (e) {
            console.warn("[UI] coinPicker search error:", e.message);
                        results.innerHTML = `<div class="picker-item muted">⚠️ ${esc(e.message)}</div>`;
            results.classList.remove("hidden");
          }
        }, 350)
      : (() => {
          console.warn("[UI] W.debounce not available");
        })();

    input.addEventListener("input", doSearch);

    input.addEventListener("focus", () => {
      if (results.innerHTML) results.classList.remove("hidden");
    });

    document.addEventListener("click", (e) => {
      if (!container.contains(e.target)) results.classList.add("hidden");
    });
  },

  spinner() {
    return '<div class="spinner"></div>';
  },

  empty(icon, msg, sub = "") {
    return `
      <div class="empty">
        <div class="empty-icon">${icon}</div>
        <p>${msg}</p>
        ${sub ? `<p class="muted small">${sub}</p>` : ""}
      </div>
    `;
  },
};

console.log("[UI] Module loaded.");
// ---- js/ui/vault-unlock.js ----
// ================================================================
// Vault Unlock View
// ================================================================
// Rendered by the router when #/unlock is reached and a vault exists.
// Setup (creating a new vault) lives in Settings → Security, not
// here — the unlock view is only for users who already opted in.

window.W = window.W || {};

W.vaultUnlock = (() => {
  "use strict";

  function render(view) {
    if (!view) return;

    if (!W.vault || !W.vault.hasStoredVault()) {
      location.hash = "#/dashboard";
      return;
    }
    if (W.vault.isUnlocked()) {
      const target =
        sessionStorage.getItem("post_unlock_route") || "dashboard";
      sessionStorage.removeItem("post_unlock_route");
      location.hash = "#/" + target;
      return;
    }

    view.innerHTML = `
      <div class="card vault-unlock-card">
        <h2>🔓 Unlock Weaver</h2>
        <p class="muted small">
          Your data is encrypted with a passphrase only you know. It
          is not stored anywhere. If you forget it, the encrypted
          data cannot be recovered.
        </p>
        <label>
          Passphrase
          <input type="password" id="vault-pw" autocomplete="current-password" spellcheck="false" class="w-100">
        </label>
        <p id="vault-error" class="down small hidden"></p>
        <button class="btn primary mt" id="vault-unlock-go" type="button">Unlock</button>
      </div>
    `;

    const pw = view.querySelector("#vault-pw");
    const errEl = view.querySelector("#vault-error");
    const btn = view.querySelector("#vault-unlock-go");

    function showError(msg) {
      errEl.textContent = msg;
      errEl.classList.remove("hidden");
    }

    async function submit() {
      if (btn.disabled) return;
      btn.disabled = true;
      btn.textContent = "Unlocking…";
      const value = pw.value;
      if (!value) {
        showError("Passphrase required.");
        btn.disabled = false;
        btn.textContent = "Unlock";
        return;
      }
      try {
        await W.vault.unlock(value);
        const target =
          sessionStorage.getItem("post_unlock_route") || "dashboard";
        sessionStorage.removeItem("post_unlock_route");
        location.hash = "#/" + target;
      } catch (e) {
        showError(e && e.message ? e.message : "Unlock failed.");
        btn.disabled = false;
        btn.textContent = "Unlock";
        pw.select();
      }
    }

    btn.onclick = submit;
    pw.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        submit();
      }
    });
    setTimeout(() => pw.focus(), 30);
  }

  return Object.freeze({ render });
})();

console.log("[VaultUnlock] Module loaded.");
// ---- js/ui/data-status.js ----
// ===============================================================
// Data freshness status UI
// ===============================================================

window.W = window.W || {};
W.ui = W.ui || {};

W.ui.renderDataStatus = function (container, resources = []) {
  if (!container) return;
  container.replaceChildren();
  const statuses = resources.map(
    (resource) =>
      W.dataHealth?.get(resource) || {
        resource,
        source: "unknown",
        state: "unknown",
        ageMs: null,
      },
  );
  const stale = statuses.filter((item) => item.state === "stale");
  const unknown = statuses.filter((item) => item.state === "unknown");
  const wrapper = document.createElement("div");
  wrapper.className = `data-status ${stale.length ? "data-status-stale" : "data-status-ok"}`;
  const title = document.createElement("strong");
  title.textContent = stale.length ? "⚠ Data may be stale" : "✓ Data freshness";
  wrapper.appendChild(title);

  const details = document.createElement("span");
  details.className = "data-status-details";
  details.textContent = statuses
    .map((item) => {
      const label = item.resource.replaceAll("-", " ");
      if (item.state === "unknown") return `${label}: unavailable`;
      const age = formatAge(item.ageMs);
      return `${label}: ${age} (${item.source})`;
    })
    .join(" · ");
  wrapper.appendChild(details);

  if (unknown.length || stale.length) {
    const note = document.createElement("span");
    note.className = "data-status-note";
    note.textContent = "Verify important decisions against a current source.";
    wrapper.appendChild(note);
  }
  container.appendChild(wrapper);
};

function formatAge(ageMs) {
  if (!Number.isFinite(ageMs)) return "unknown age";
  const minutes = Math.floor(ageMs / 60000);
  if (minutes < 1) return "just now";
  if (minutes < 60) return `${minutes}m old`;
  const hours = Math.floor(minutes / 60);
  if (hours < 24) return `${hours}h old`;
  return `${Math.floor(hours / 24)}d old`;
}

W.ui.formatDataAge = formatAge;
console.log("[DataStatus] Freshness UI loaded.");
// ---- js/ui/dashboard.js ----
// ===============================================================
//                Weaver Dashboard
// ===============================================================

window.W = window.W || {};

W.dashboard = (() => {
  const MODULE_VERSION = "dashboard-v3.5";
  const MARKET_ROWS_DEFAULT = 10;
  let marketRowsExpanded = false;

  // ── Last-known-good price cache (§3.6, §3.4) ─────────────────
  const PRICE_CACHE_KEY = "last_known_prices";
  const readPriceCache = () => W.store.get(PRICE_CACHE_KEY, {});

  // Safe fallback if skeleton module isn't loaded yet
  const skel = (W.ui && W.ui.skeleton) || {
    stats: (n) => Array(n).fill('<div class="spinner"></div>').join(""),
    card: () => '<div class="spinner"></div>',
    chart: () => '<div class="spinner"></div>',
    feed: (n) => Array(n).fill('<div class="spinner"></div>').join(""),
    table: (n) => Array(n).fill('<div class="spinner"></div>').join(""),
  };

  // ── Escaping helper ─────────────────────────────────────────
  const esc =
    (W.fmt && W.fmt.escapeHTML) ||
    function (v) {
      if (v == null) return "";
      return String(v).replace(
        /[&<>"']/g,
        (c) =>
          ({
            "&": "&amp;",
            "<": "&lt;",
            ">": "&gt;",
            '"': "&quot;",
            "'": "&#39;",
          })[c],
      );
    };

  const signedMoney = (n) => {
    if (n == null || isNaN(n)) return "—";
    const isUp = n >= 0;
    const cls = isUp ? "up" : "down";
    return `<span class="${cls}">${isUp ? "+" : "-"}${W.fmt.money(Math.abs(n))}</span>`;
  };

  // ── Signal drawer opener ─────────────────────────────────
  // The evidence drawer's open() expects an object with a
  // `domains` map. The dashboard historically passed a raw
  // signalId string, which the drawer coerced to {} and rendered
  // empty. This helper does the decision lookup and builds the
  // shape the drawer understands.
  //
  // Decision-row relationship is derived from recommendedAction:
  //   ACT       → supporting   (the engine is telling you to act on it)
  //   EXIT      → contradicting (the engine is telling you to leave)
  //   REVIEW    → unknown       (worth a look; not a directional call)
  //   MONITOR   → unknown
  //   IGNORE    → unknown
  function openSignalDrawer(signalId, decisions) {
    if (!signalId || !W.ui?.evidenceDrawer?.open) return;

    const decision = Array.isArray(decisions)
      ? decisions.find((d) => d && d.signalId === signalId)
      : null;

    if (!decision) {
      // The signal list moved on between the click-handler bind
      // and the click. Open an honest empty drawer rather than a
      // populated-looking lie.
      try {
        W.ui.evidenceDrawer.open({
          explanation: "This signal is no longer in the current decision set.",
        });
      } catch (e) {
        console.warn("[Dashboard] drawer open failed:", e?.message);
      }
      return;
    }

    const action = decision.recommendedAction;
    const relationship =
      action === "ACT"
        ? "supporting"
        : action === "EXIT"
          ? "contradicting"
          : "unknown";

    const reliability = Number.isFinite(decision.assessment?.confidence)
      ? Math.max(0, Math.min(1, decision.assessment.confidence))
      : undefined;

    try {
      W.ui.evidenceDrawer.open({
        explanation: decision.explanation,
        methodologyVersion: decision.methodologyVersion,
        domains: {
          signal: {
            status: decision.eligibility || "unknown",
            relationship,
            source: decision._signalType || "signal",
            reliability,
            reasons: Array.isArray(decision.assessment?.reasoning)
              ? decision.assessment.reasoning.slice()
              : [],
          },
        },
      });
    } catch (e) {
      console.warn("[Dashboard] drawer open failed:", e?.message);
    }
  }

  // ── Tape (market strip) ─────────────────────────────────────
  const tapeHTML = (coins) => {
    if (!coins || !Array.isArray(coins) || !coins.length) {
      return '<div class="tape-wrap"><div class="tape"><span class="tape-item text-muted">Loading market data…</span></div></div>';
    }
    let tapeItems = "";
    let validCount = 0;
    for (let i = 0; i < coins.length; i++) {
      const c = coins[i];
      if (!c || typeof c !== "object") continue;
      const symbol = c.symbol ? String(c.symbol).toUpperCase() : null;
      if (!symbol) continue;
      const price =
        c.current_price !== undefined
          ? c.current_price
          : c.price !== undefined
            ? c.price
            : null;
      if (price === null || price === undefined || isNaN(price)) continue;
      const change =
        c.price_change_percentage_24h_in_currency !== undefined
          ? c.price_change_percentage_24h_in_currency
          : 0;
      tapeItems += `<span class="tape-item"><b>${esc(symbol)}</b><span class="text-muted">${W.fmt.price(price)}</span>${W.fmt.pct(change)}</span>`;
      validCount++;
      if (validCount >= 20) break;
    }
    if (!tapeItems)
      return '<div class="tape-wrap"><div class="tape"><span class="tape-item text-muted">No market data available</span></div></div>';
    return `<div class="tape-wrap"><div class="tape">${tapeItems + tapeItems}</div></div>`;
  };

  // ── Chart colors ────────────────────────────────────────────
  const CHART_COLORS = [
    "#10b981",
    "#6366f1",
    "#f59e0b",
    "#ef4444",
    "#8b5cf6",
    "#06b6d4",
    "#ec4899",
    "#84cc16",
  ];

  function cssVar(name, fallback) {
    try {
      const v = getComputedStyle(document.documentElement)
        .getPropertyValue(name)
        .trim();
      return v || fallback;
    } catch {
      return fallback;
    }
  }

  // ── Sparkline (canvas) — used only where real series data exists ──
  function drawSpark(c) {
    const vals = (c.dataset.spark || "")
      .split(",")
      .map(Number)
      .filter((v) => !isNaN(v));
    if (vals.length < 2) return;
    const w = (c.width = 110),
      h = (c.height = 30),
      ctx = c.getContext("2d");
    if (!ctx) return;
    const min = Math.min(...vals),
      max = Math.max(...vals),
      up = c.dataset.up === "1";
    const colorUp = cssVar("--up", "#10b981");
    const colorDown = cssVar("--down", "#ef4444");
    const strokeColor = up ? colorUp : colorDown;
    const fillColor = up
      ? "rgba(16, 185, 129, 0.12)"
      : "rgba(239, 68, 68, 0.12)";

    ctx.clearRect(0, 0, w, h);
    ctx.strokeStyle = strokeColor;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    vals.forEach((v, i) => {
      const x = (i / (vals.length - 1)) * w,
        y = h - 3 - ((v - min) / (max - min || 1)) * (h - 6);
      i ? ctx.lineTo(x, y) : ctx.moveTo(x, y);
    });
    ctx.stroke();
    ctx.lineTo(w, h);
    ctx.lineTo(0, h);
    ctx.closePath();
    ctx.fillStyle = fillColor;
    ctx.fill();
  }

  const sparkCell = (arr, up) =>
    arr && arr.length
      ? `<canvas class="spark" data-up="${up ? 1 : 0}" data-spark="${arr
          .filter((_, i) => i % 6 === 0)
          .map((v) => v.toFixed(4))
          .join(",")}"></canvas>`
      : '<span class="text-muted small-text">—</span>';

  // ── Logo or letter avatar ───────────────────────────────────
  function avatarSlot(sym) {
    let hash = 0;
    for (let i = 0; i < sym.length; i++) {
      hash = (hash * 31 + sym.charCodeAt(i)) | 0;
    }
    return Math.abs(hash) % 10;
  }

  function safeImageUrl(u) {
    if (typeof u !== "string" || !u) return null;
    try {
      const parsed = new URL(u);
      if (parsed.protocol !== "https:") return null;
      if (!parsed.hostname.endsWith("coingecko.com")) return null;
      return parsed.toString();
    } catch {
      return null;
    }
  }

  function avatarMarkup(symbol, imageUrl, extraClass) {
    const sym = String(symbol || "?").toUpperCase();
    const slot = avatarSlot(sym);
    const initials = sym.slice(0, 3);
    const cls = extraClass ? ` ${extraClass}` : "";

    const safe = safeImageUrl(imageUrl);
    if (!safe) {
      return `<span class="token-avatar token-avatar-slot-${slot}${cls}" aria-hidden="true"><span class="token-avatar-text">${esc(initials)}</span></span>`;
    }

    return `<img class="token-avatar-img${cls}" src="${esc(safe)}" alt="" loading="lazy" decoding="async" width="32" height="32" data-fallback-symbol="${esc(sym)}">`;
  }

  function wireAvatarFallbacks(root) {
    if (!root || typeof root.querySelectorAll !== "function") return;
    root.querySelectorAll("img[data-fallback-symbol]").forEach((img) => {
      const swap = () => {
        const sym = img.dataset.fallbackSymbol || "?";
        const slot = avatarSlot(sym);
        const span = document.createElement("span");
        span.className = `token-avatar token-avatar-slot-${slot}`;
        span.setAttribute("aria-hidden", "true");
        const inner = document.createElement("span");
        inner.className = "token-avatar-text";
        inner.textContent = sym.slice(0, 3);
        span.appendChild(inner);
        if (img.parentNode) img.parentNode.replaceChild(span, img);
      };
      if (img.complete && img.naturalWidth === 0) {
        swap();
      } else {
        img.addEventListener("error", swap, { once: true });
      }
    });
  }

  // ── Top-tokens row ──────────────────────────────────────────
  const tokenRow = (c, i) => {
    if (!c || typeof c !== "object") return "";
    const id = c.id || "unknown";
    const name = c.name || "Unknown";
    const symbol = c.symbol ? String(c.symbol).toUpperCase() : "???";
    const price = Number.isFinite(c.current_price)
      ? c.current_price
      : Number.isFinite(c.price)
        ? c.price
        : null;
    const p24 = Number.isFinite(c.price_change_percentage_24h_in_currency)
      ? c.price_change_percentage_24h_in_currency
      : null;
    const mcap = Number.isFinite(c.market_cap) ? c.market_cap : null;
    const changeCls = p24 === null ? "" : p24 >= 0 ? "up" : "down";
    const priceText =
      price === null
        ? "—"
        : price >= 1
          ? "$" + price.toFixed(2)
          : "$" + price.toFixed(6);
    const changeText = p24 === null ? "—" : W.fmt.pct(p24);
    const mcapText =
      mcap === null
        ? "—"
        : "$" +
          (mcap >= 1e9
            ? (mcap / 1e9).toFixed(2) + "B"
            : (mcap / 1e6).toFixed(2) + "M");

    return `
      <button type="button" class="token-row" data-coin="${esc(id)}">
        <span class="token-rank">${esc(i + 1)}</span>
        <span class="token-ident">
          ${avatarMarkup(symbol, c.image)}
          <span class="token-ident-text">
            <span class="token-symbol">${esc(symbol)}</span>
            <span class="token-name">${esc(name)}</span>
          </span>
        </span>
        <span class="token-price">${esc(priceText)}</span>
        <span class="token-change ${changeCls}">${esc(changeText)}</span>
        <span class="token-mcap">${esc(mcapText)}</span>
      </button>
    `;
  };

  // ── Enrichment: honest prices + honest cost basis ────────────
  async function enrich() {
    const manualHoldings = W.portfolio ? W.portfolio.all() : [];
    const walletHoldings = W.walletSync?.holdings
      ? W.walletSync.holdings()
      : [];
    const allHoldings = [
      ...manualHoldings.map((h) => ({ ...h, wallet: false })),
      ...walletHoldings.map((h) => ({ ...h, wallet: true })),
    ];
    if (!allHoldings.length) return { rows: [], totals: null };

    const ids = [...new Set(allHoldings.map((h) => h.coinId))]
      .filter(Boolean)
      .join(",");
    let markets = [];
    if (ids.trim()) {
      try {
        markets = await W.api.markets(ids);
      } catch (e) {
        console.warn("[Dashboard] Market fetch failed:", e.message);
      }
    }

    const priceCache = readPriceCache();
    let cacheDirty = false;

    const rows = allHoldings
      .map((h) => {
        const m = markets.find((c) => c.id === h.coinId) || {};

        let price = Number.isFinite(m.current_price) ? m.current_price : null;
        let priceStale = false;

        if (price !== null) {
          priceCache[h.coinId] = { price, ts: Date.now() };
          cacheDirty = true;
        } else if (
          priceCache[h.coinId] &&
          Number.isFinite(priceCache[h.coinId].price)
        ) {
          price = priceCache[h.coinId].price;
          priceStale = true;
        }

        const qty = parseFloat(h.qty) || 0;
        const value = price !== null ? price * qty : null;

        let cost = null;
        if (h.wallet) {
          if (
            h.manualCostBasis &&
            typeof h.manualCostBasis.totalCost === "number"
          )
            cost = h.manualCostBasis.totalCost;
        } else if (
          h.totalCost !== undefined &&
          h.totalCost !== null &&
          !isNaN(h.totalCost) &&
          h.totalCost >= 0
        ) {
          cost = h.totalCost;
        } else {
          const bp = parseFloat(h.buyPrice);
          if (!isNaN(bp) && bp >= 0) cost = bp * qty;
        }

        const pnl = value !== null && cost !== null ? value - cost : null;
        const pnlPct = pnl !== null && cost > 0 ? (pnl / cost) * 100 : null;

        return {
          ...h,
          price,
          priceStale,
          value,
          cost,
          pnl,
          pnlPct,
          p24: Number.isFinite(m.price_change_percentage_24h_in_currency)
            ? m.price_change_percentage_24h_in_currency
            : null,
          image: m.image || h.img,
        };
      })
      .sort((a, b) => (b.value ?? -1) - (a.value ?? -1));

    if (cacheDirty) W.store.set(PRICE_CACHE_KEY, priceCache);

    const totals = {
      value: 0,
      cost: 0,
      priced: 0,
      unpriced: 0,
      unknownCost: 0,
    };
    let prev24 = 0;
    rows.forEach((r) => {
      if (r.value !== null) {
        totals.value += r.value;
        totals.priced++;
        if (r.p24 != null) prev24 += r.value / (1 + r.p24 / 100);
      } else {
        totals.unpriced++;
      }
      if (r.cost !== null) totals.cost += r.cost;
      else if (r.value !== null) totals.unknownCost++;
    });

    totals.allTime = totals.cost > 0 ? totals.value - totals.cost : null;
    totals.allTimePct =
      totals.allTime !== null ? (totals.allTime / totals.cost) * 100 : null;
    totals.day = totals.value - prev24;
    totals.dayPct = prev24 ? (totals.day / prev24) * 100 : null;
    return { rows, totals };
  }

  // ── Holdings table ──────────────────────────────────────────
  const holdingsTable = (rows) => `
    <div class="table-wrap"><table><thead><tr><th>Asset</th><th>Price</th><th>24h</th><th>Qty</th><th>Value</th><th>P/L</th><th></th></tr></thead><tbody>
      ${rows
        .map((r, i) => {
          const sym = String(r.symbol || "?").toUpperCase();
          const p24Cls = r.p24 === null ? "" : r.p24 >= 0 ? "up" : "down";
          const pnlCell =
            r.pnl !== null
              ? signedMoney(r.pnl) +
                '<div class="small-text">' +
                W.fmt.pct(r.pnlPct) +
                "</div>"
              : `<span class="text-muted small-text cost-basis-hint" title="Click the pencil to enter the total amount paid">Set cost basis</span>`;
          return `<tr>
        <td class="coin-cell">
          ${avatarMarkup(sym, r.image, "coin-img")}
          <div><b>${esc(r.name)}</b><br><span class="text-muted small-text">${esc(sym)}</span></div>
        </td>
        <td class="num">${r.price !== null ? W.fmt.price(r.price) + (r.priceStale ? ' <span class="text-muted small-text">·stale</span>' : "") : '<span class="text-muted">—</span>'}</td>
        <td class="num ${p24Cls}">${r.p24 !== null ? W.fmt.pct(r.p24) : '<span class="text-muted">—</span>'}</td>
        <td class="num">${r.qty}</td>
        <td class="num">${r.value !== null ? `<b>${W.fmt.money(r.value)}</b>` : '<span class="text-muted">—</span>'}</td>
        <td class="num">${pnlCell}</td>
        <td class="row-actions">${
          r.wallet
            ? `<span class="tag rank">wallet</span> <button class="icon-btn" data-basis="${i}" title="Set cost basis">✎</button>`
            : `<button class="icon-btn" data-edit="${esc(r.id)}" title="Edit">✎</button><button class="icon-btn" data-del="${esc(r.id)}" title="Remove">✕</button>`
        }</td>
      </tr>`;
        })
        .join("")}
    </tbody></table></div>`;

  function wireRows(container, rows) {
    rows.forEach((r, i) => {
      if (r.wallet) {
        const b = container.querySelector(`[data-basis="${i}"]`);
        if (b) b.onclick = () => basisModal(r);
        return;
      }
      const e = container.querySelector(`[data-edit="${CSS.escape(r.id)}"]`);
      const d = container.querySelector(`[data-del="${CSS.escape(r.id)}"]`);
      if (e) e.onclick = () => holdingModal(r);
      if (d)
        d.onclick = () =>
          W.ui.confirm(`Remove <b>${esc(r.name)}</b>?`, () => {
            if (W.portfolio && W.portfolio.remove) W.portfolio.remove(r.id);
            W.ui.toast("Holding removed", "ok");
            W.refresh();
          });
    });
  }

  // ── Manual Cost Basis Modal (wallet holdings) ───────────────
  function basisModal(r) {
    const existing = r.manualCostBasis;
    const m = W.ui.modal({
      title: `Cost basis — ${esc(r.symbol)}`,
      body: `<p class="text-muted small-text">Wallet sync cannot know your purchase history. Enter the <b>total amount paid</b> for this position so P/L is truthful. Leave empty to keep P/L unknown.</p>
        <label>Total cost (${esc(W.currency().toUpperCase())})<input type="number" step="any" min="0" id="b-cost" value="${existing ? existing.totalCost : ""}" placeholder="e.g. 500"></label>`,
      footer: `<button class="btn ghost" id="b-cancel">Cancel</button><button class="btn primary" id="b-save">Save</button>`,
    });
    m.el.querySelector("#b-cancel").onclick = m.close;
    m.el.querySelector("#b-save").onclick = () => {
      const raw = m.el.querySelector("#b-cost").value.trim();
      const total = raw === "" ? null : parseFloat(raw);
      if (total !== null && (!Number.isFinite(total) || total < 0))
        return W.ui.toast("Enter a valid non-negative cost", "warn");

      const basisMap = W.store.get("wallet_cost_basis", {});
      const key = `${r.walletChain}:${r.symbol}:${r.contractAddress ? String(r.contractAddress).toLowerCase() : "native"}`;

      if (total === null) delete basisMap[key];
      else basisMap[key] = { totalCost: total, updatedAt: Date.now() };

      W.store.set("wallet_cost_basis", basisMap);
      m.close();
      W.ui.toast("Cost basis saved", "ok");
      W.refresh();
    };
  }

  function holdingModal(existing = null, preselect = null) {
    const coinLine = existing
      ? `<p class="text-muted small-text">Coin: <b>${esc(existing.name)} (${esc(existing.symbol.toUpperCase())})</b></p>`
      : preselect
        ? `<p class="text-muted small-text">Coin: <b>${esc(preselect.name)} (${esc(preselect.symbol.toUpperCase())})</b></p>`
        : `<div id="picker"></div>`;
    const m = W.ui.modal({
      title: existing ? `Edit ${esc(existing.name)}` : "Add Holding",
      body: `<form id="h-form">${coinLine}<label>Quantity<input type="number" step="any" name="qty" required value="${existing ? existing.qty : ""}" placeholder="0.5"></label><label>Average buy price<input type="number" step="any" name="buyPrice" required value="${existing ? existing.buyPrice : ""}" placeholder="29500"></label></form>`,
      footer: `<button class="btn ghost" id="h-cancel">Cancel</button><button class="btn primary" id="h-save">${existing ? "Save" : "Add"}</button>`,
    });
    let picked = existing
      ? {
          id: existing.coinId,
          symbol: existing.symbol,
          name: existing.name,
          img: existing.img,
        }
      : preselect
        ? {
            id: preselect.id,
            symbol: preselect.symbol,
            name: preselect.name,
            img: preselect.image?.small || "",
          }
        : null;
    if (!existing && !preselect && W.ui.coinPicker)
      W.ui.coinPicker(m.el.querySelector("#picker"), (p) => (picked = p));
    m.el.querySelector("#h-cancel").onclick = m.close;
    m.el.querySelector("#h-save").onclick = () => {
      const f = m.el.querySelector("#h-form");
      const qty = parseFloat(f.qty.value),
        buyPrice = parseFloat(f.buyPrice.value);
      if (!picked) return W.ui.toast("Pick a coin first", "warn");
      if (!qty || qty <= 0 || isNaN(buyPrice) || buyPrice < 0)
        return W.ui.toast("Enter valid quantity and price", "warn");
      if (existing && W.portfolio && W.portfolio.update)
        W.portfolio.update(existing.id, { qty, buyPrice });
      else if (W.portfolio && W.portfolio.add)
        W.portfolio.add({
          coinId: picked.id,
          symbol: picked.symbol,
          name: picked.name,
          img: picked.img,
          qty,
          buyPrice,
          date: Date.now(),
        });
      m.close();
      W.ui.toast(existing ? "Holding updated" : "Holding added", "ok");
      W.refresh();
    };
  }

  // ── Chart lifecycle ────────────────────────────────────────
  function destroyCharts(view) {
    if (!view) return;
    for (const k of ["_dashboardPerfChart", "_dashboardDonut"]) {
      if (view[k]) {
        try {
          view[k].destroy();
        } catch (_) {}
        view[k] = null;
      }
    }
  }

  function snapshotsToSeries(rangeDays) {
    if (!W.timemachine || typeof W.timemachine.getSnapshots !== "function")
      return [];
    let snaps = W.timemachine.getSnapshots();
    if (!Array.isArray(snaps) || !snaps.length) return [];
    snaps = snaps.slice().sort((a, b) => a.timestamp - b.timestamp);
    if (rangeDays != null) {
      const cutoff = Date.now() - rangeDays * 864e5;
      snaps = snaps.filter((s) => s.timestamp >= cutoff);
    }
    return snaps
      .map((s) => {
        const v = s?.totals?.totalValue;
        return typeof v === "number" && Number.isFinite(v)
          ? { t: s.timestamp, y: v }
          : null;
      })
      .filter(Boolean);
  }

  function formatChartDate(ts) {
    const d = new Date(ts);
    return `${d.getMonth() + 1}/${d.getDate()}`;
  }

  function drawPerformanceChart(view) {
    const canvas = view.querySelector("#d-perf-chart");
    const note = view.querySelector("#d-perf-note");
    const rangeEl = view.querySelector("#d-perf-range");
    if (!canvas) return;
    if (view._dashboardPerfChart) {
      try {
        view._dashboardPerfChart.destroy();
      } catch (_) {}
      view._dashboardPerfChart = null;
    }

    const active = rangeEl?.querySelector(".dash-range-btn.active");
    const rangeVal = active?.dataset?.range;
    const rangeDays =
      !rangeVal || rangeVal === "all"
        ? null
        : Number.isFinite(Number(rangeVal))
          ? Number(rangeVal)
          : null;
    const series = snapshotsToSeries(rangeDays);

    if (series.length < 2) {
      if (note)
        note.textContent =
          series.length === 0
            ? "No portfolio snapshots yet — history builds as you use Weaver."
            : "Only one snapshot captured so far. Check back after the next refresh cycle.";
      const wrap = canvas.parentElement;
      if (wrap) {
        const w = (canvas.width = wrap.clientWidth || 400);
        const h = (canvas.height = wrap.clientHeight || 220);
        const ctx = canvas.getContext("2d");
        if (ctx) {
          ctx.clearRect(0, 0, w, h);
          ctx.strokeStyle = "rgba(255,255,255,0.06)";
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(0, h - 1);
          ctx.lineTo(w, h - 1);
          ctx.stroke();
        }
      }
      return;
    }
    if (note) note.textContent = "";
    if (typeof Chart !== "function") {
      if (note) note.textContent = "Chart library unavailable.";
      return;
    }

    const isUp = series[series.length - 1].y >= series[0].y;
    const colorLine = isUp
      ? cssVar("--up", "#10b981")
      : cssVar("--down", "#ef4444");
    const fillTop = isUp
      ? "rgba(16, 185, 129, 0.25)"
      : "rgba(239, 68, 68, 0.25)";
    const fillBottom = isUp ? "rgba(16, 185, 129, 0)" : "rgba(239, 68, 68, 0)";

    view._dashboardPerfChart = new Chart(canvas, {
      type: "line",
      data: {
        labels: series.map((p) => formatChartDate(p.t)),
        datasets: [
          {
            label: "Portfolio value",
            data: series.map((p) => p.y),
            borderColor: colorLine,
            backgroundColor: (context) => {
              const ctx = context.chart.ctx;
              const gradient = ctx.createLinearGradient(0, 0, 0, 300);
              gradient.addColorStop(0, fillTop);
              gradient.addColorStop(1, fillBottom);
              return gradient;
            },
            borderWidth: 2,
            pointRadius: 0,
            pointHoverRadius: 5,
            pointHoverBackgroundColor: colorLine,
            fill: true,
            tension: 0.3,
          },
        ],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        interaction: { mode: "index", intersect: false },
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              label: (c) => {
                const v = c.parsed?.y;
                return Number.isFinite(v) ? W.fmt.money(v) : "—";
              },
            },
          },
        },
        scales: {
          x: {
            grid: { display: false },
            ticks: {
              color: "#8b94a7",
              font: { size: 10 },
              maxRotation: 0,
              autoSkip: true,
              maxTicksLimit: 8,
            },
          },
          y: {
            grid: { color: "rgba(255,255,255,0.04)" },
            ticks: {
              color: "#8b94a7",
              font: { size: 10 },
              callback: (v) => W.fmt.money(v, { compact: true }),
            },
          },
        },
      },
    });
  }

  // ── Allocation donut ───────────────────────────────────────
  const ALLOCATION_TOP_N = 5;

  function buildAllocation(rows, totals) {
    const priced = rows.filter((r) => r.value !== null && r.value > 0);
    if (!priced.length || !totals || !totals.value) return null;
    const total = totals.value;
    const sorted = priced.slice().sort((a, b) => b.value - a.value);
    const top = sorted.slice(0, ALLOCATION_TOP_N);
    const restSum = sorted
      .slice(ALLOCATION_TOP_N)
      .reduce((s, r) => s + r.value, 0);

    const segments = top.map((r, i) => ({
      symbol: String(r.symbol || "?").toUpperCase(),
      value: r.value,
      pct: (r.value / total) * 100,
      color: CHART_COLORS[i % CHART_COLORS.length],
    }));
    if (restSum > 0) {
      segments.push({
        symbol: "Others",
        value: restSum,
        pct: (restSum / total) * 100,
        color: CHART_COLORS[segments.length % CHART_COLORS.length],
      });
    }
    return { segments, total };
  }

  function drawAllocationDonut(view, alloc) {
    const canvas = view.querySelector("#d-donut");
    const totalEl = view.querySelector("#d-donut-total");
    const legend = view.querySelector("#d-legend");
    if (!canvas) return;
    if (view._dashboardDonut) {
      try {
        view._dashboardDonut.destroy();
      } catch (_) {}
      view._dashboardDonut = null;
    }

    if (!alloc) {
      if (totalEl) totalEl.textContent = "—";
      if (legend)
        legend.innerHTML =
          '<p class="text-muted small-text">Add priced holdings to see allocation.</p>';
      return;
    }

    if (totalEl) totalEl.textContent = W.fmt.money(alloc.total);
    if (legend) {
      legend.innerHTML = alloc.segments
        .map(
          (s) => `
            <div class="dash-legend-row">
              <span class="dash-legend-dot" data-color="${esc(s.color)}"></span>
              <span class="dash-legend-label">${esc(s.symbol)}</span>
              <span class="dash-legend-pct">${s.pct.toFixed(1)}%</span>
            </div>
          `,
        )
        .join("");
      legend.querySelectorAll(".dash-legend-dot").forEach((el) => {
        const c = el.dataset.color;
        if (c) el.style.background = c;
      });
    }

    if (typeof Chart !== "function") return;
    view._dashboardDonut = new Chart(canvas, {
      type: "doughnut",
      data: {
        labels: alloc.segments.map((s) => s.symbol),
        datasets: [
          {
            data: alloc.segments.map((s) => s.value),
            backgroundColor: alloc.segments.map((s) => s.color),
            borderWidth: 0,
            spacing: 2,
          },
        ],
      },
      options: {
        responsive: true,
        maintainAspectRatio: false,
        cutout: "68%",
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              label: (c) => `${c.label}: ${W.fmt.money(c.parsed)}`,
            },
          },
        },
      },
    });
  }

  // ── Fear & Greed gauge ─────────────────────────────────────
  function renderFearGreed(fg) {
    const value = Number(fg?.value);
    if (!Number.isFinite(value)) {
      return `<p class="muted small p-16">Sentiment data unavailable.</p>`;
    }
    const label = String(fg.value_classification || "Neutral");
    const angle = (value / 100) * 180;
    const rad = (angle - 90) * (Math.PI / 180);
    const cx = 100;
    const cy = 90;
    const r = 70;
    const nx = cx + r * Math.cos(rad);
    const ny = cy + r * Math.sin(rad);

    return `
      <div class="fg-card">
        <svg class="fg-gauge" viewBox="0 0 200 110" aria-label="Fear and Greed Index">
          <defs>
            <linearGradient id="fgGradient" x1="0" y1="0" x2="1" y2="0">
              <stop offset="0%"   stop-color="#ef4444" />
              <stop offset="50%"  stop-color="#f59e0b" />
              <stop offset="100%" stop-color="#10b981" />
            </linearGradient>
          </defs>
          <path d="M 30 90 A 70 70 0 0 1 170 90" fill="none"
                stroke="url(#fgGradient)" stroke-width="12" stroke-linecap="round" />
          <line x1="${cx}" y1="${cy}"
                x2="${nx.toFixed(1)}" y2="${ny.toFixed(1)}"
                stroke="#eef1f9" stroke-width="3" stroke-linecap="round" />
          <circle cx="${cx}" cy="${cy}" r="5" fill="#eef1f9" />
        </svg>
        <div class="fg-value">${Math.round(value)}</div>
        <div class="fg-label">${esc(label)}</div>
        <div class="fg-timestamp">Updated ${esc(new Date().toLocaleDateString())}</div>
      </div>
    `;
  }

  // ── BTC dominance card ────────────────────────────────────
  function renderDominance(g) {
    const dom = Number(g?.data?.market_cap_percentage?.btc);
    const change = Number(g?.data?.market_cap_change_percentage_24h_usd);
    const domText = Number.isFinite(dom) ? dom.toFixed(1) + "%" : "—";
    const changeCls = !Number.isFinite(change)
      ? "muted"
      : change >= 0
        ? "up"
        : "down";
    const changeText = Number.isFinite(change) ? W.fmt.pct(change) : "—";

    return `
      <div class="dash-card-title">BTC Dominance</div>
      <div class="dom-value">${esc(domText)}</div>
      <div class="dom-delta ${changeCls}">${esc(changeText)} (24h)</div>
      <p class="muted small-text mt-8">Share of total crypto market cap held by BTC.</p>
    `;
  }

  // ── Recent signals list ───────────────────────────────────
  function renderSignals(decisions) {
    if (!Array.isArray(decisions) || !decisions.length) {
      return `<p class="muted small p-16">No recent signals.</p>`;
    }
    const rows = decisions.slice(0, 6);

    return `<div class="dash-signals-list">${rows
      .map((d) => {
        const sym = esc(
          String(d._assetSymbol || d.assetId?.symbol || "—").toUpperCase(),
        );
        const kind = esc(
          String(d._signalTitle || d._signalType || "Signal").slice(0, 64),
        );
        const conf =
          d.assessment && Number.isFinite(d.assessment.confidence)
            ? d.assessment.confidence
            : null;
        const confText = conf === null ? "—" : `${Math.round(conf * 100)}%`;
        const confClass = conf === null ? "muted" : conf >= 0.6 ? "up" : "warn";

        const type = d._signalType || "";
        const isDown =
          type === "THESIS_DETERIORATION" || type === "SECURITY_RISK";
        const iconCls = isDown ? "signal-icon-down" : "signal-icon-up";
        const icon = isDown ? "↓" : "↑";

        const sigId = esc(d.signalId || "");

        return `
          <button type="button" class="signal-row" data-signal-id="${sigId}">
            <span class="signal-icon ${iconCls}" aria-hidden="true">${icon}</span>
            <span class="signal-body">
              <span class="signal-symbol">${sym}</span>
              <span class="signal-kind">${kind}</span>
            </span>
            <span class="signal-meta">
              <span class="signal-confidence ${confClass}">${confText}</span>
            </span>
          </button>
        `;
      })
      .join("")}</div>`;
  }

  // ── Evidence preview ──────────────────────────────────────
  function renderEvidencePreview(decisions) {
    if (!Array.isArray(decisions) || !decisions.length) {
      return `<p class="muted small p-16">No evidence available.</p>`;
    }
    return `<div class="evidence-preview">${decisions
      .slice(0, 4)
      .map((d) => {
        const sym = esc(
          String(d._assetSymbol || d.assetId?.symbol || "—").toUpperCase(),
        );
        const kind = esc(
          String(d._signalTitle || d._signalType || "").slice(0, 48),
        );
        const conf =
          d.assessment && Number.isFinite(d.assessment.confidence)
            ? d.assessment.confidence
            : null;
        const confText =
          conf === null ? "—" : `${Math.round(conf * 100)}% confidence`;
        const isDown = (d._signalType || "") === "THESIS_DETERIORATION";
        const iconCls = isDown ? "signal-icon-down" : "signal-icon-up";
        const icon = isDown ? "↘" : "↗";
        const sigId = esc(d.signalId || "");

        return `
          <button type="button" class="evidence-preview-row" data-signal-id="${sigId}">
            <span class="signal-icon ${iconCls}" aria-hidden="true">${icon}</span>
            <span class="evidence-preview-body">
              <span class="evidence-preview-title">${sym} — ${kind}</span>
              <span class="evidence-preview-sub">Signal: ${confText}</span>
            </span>
            <span class="evidence-preview-arrow" aria-hidden="true">›</span>
          </button>
        `;
      })
      .join("")}</div>`;
  }

  // ── Quick actions ─────────────────────────────────────────
  function renderQuickActions() {
    const actions = [
      { icon: "+", label: "Add Token", route: "/portfolio" },
      { icon: "⟐", label: "Sync Wallet", route: "/walletsync" },
      { icon: "▤", label: "View Portfolio", route: "/portfolio" },
      { icon: "◎", label: "Open Evidence", route: "/market" },
    ];
    return `<div class="quick-actions">${actions
      .map(
        (a) => `
        <button type="button" class="quick-action" data-route="${esc(a.route)}">
          <span class="quick-action-icon" aria-hidden="true">${esc(a.icon)}</span>
          <span>${esc(a.label)}</span>
        </button>
      `,
      )
      .join("")}</div>`;
  }

  // ── Key insights ──────────────────────────────────────────
  function renderInsights(decisions, fg, rows, totals) {
    const insights = [];

    const strongest = Array.isArray(decisions)
      ? decisions.find(
          (d) => d.assessment && Number.isFinite(d.assessment.confidence),
        )
      : null;
    if (strongest) {
      const sym = String(strongest._assetSymbol || "—").toUpperCase();
      const kind = String(strongest._signalType || "signal").replace(/_/g, " ");
      const conf = Math.round((strongest.assessment.confidence || 0) * 100);
      insights.push({
        icon: "↗",
        iconCls: "insight-icon-up",
        title: `${sym} signal detected`,
        text: `A ${kind.toLowerCase()} with ${conf}% confidence was detected. Review the evidence before deciding.`,
        signalId: strongest.signalId,
      });
    }

    if (fg && Number.isFinite(Number(fg.value))) {
      const v = Number(fg.value);
      const interpretation =
        v >= 55
          ? "Sentiment is elevated — historical reversions often follow."
          : v <= 45
            ? "Sentiment is defensive — historically a capitulation zone."
            : "Sentiment is neutral — a wait-and-see stance is reasonable.";
      insights.push({
        icon: "i",
        iconCls: "",
        title: "Market Sentiment",
        text: `Fear & Greed is at ${Math.round(v)} (${esc(fg.value_classification || "Neutral")}). ${interpretation}`,
        route: "/market",
      });
    }

    if (Array.isArray(rows) && rows.length && totals && totals.value > 0) {
      const top = rows
        .filter((r) => r.value !== null && r.value > 0)
        .sort((a, b) => b.value - a.value)[0];
      if (top) {
        const weight = (top.value / totals.value) * 100;
        if (weight >= 50) {
          insights.push({
            icon: "⚠",
            iconCls: "insight-icon-warn",
            title: "Concentration risk",
            text: `${String(top.symbol || "?").toUpperCase()} is ${weight.toFixed(0)}% of your portfolio. Consider whether this matches your risk tolerance.`,
            route: "/portfolio",
          });
        }
      }
    }

    if (!insights.length) {
      return `<p class="muted small p-16">No insights to surface right now.</p>`;
    }
    return insights
      .slice(0, 3)
      .map((i) => {
        const dataAttr = i.signalId
          ? `data-signal-id="${esc(i.signalId)}"`
          : `data-route="${esc(i.route || "/dashboard")}"`;
        return `
          <div class="insight-card">
            <div class="insight-icon ${esc(i.iconCls || "")}" aria-hidden="true">${esc(i.icon)}</div>
            <div class="insight-body">
              <div class="insight-title">${esc(i.title)}</div>
              <div class="insight-text">${esc(i.text)}</div>
              <button type="button" class="insight-link" ${dataAttr}>View details →</button>
            </div>
          </div>
        `;
      })
      .join("");
  }

  // ── KPI strip ─────────────────────────────────────────────
  function renderKpiStrip(decisions, totals) {
    const signalCount = Array.isArray(decisions) ? decisions.length : 0;

    let high = 0,
      mid = 0,
      low = 0;
    if (Array.isArray(decisions)) {
      for (const d of decisions) {
        const c = d.assessment?.confidence;
        if (c == null) continue;
        if (c >= 0.7) high++;
        else if (c >= 0.4) mid++;
        else low++;
      }
    }

    let aggConf = null;
    if (Array.isArray(decisions)) {
      const priced = decisions
        .map((d) => d.assessment?.confidence)
        .filter((c) => Number.isFinite(c));
      if (priced.length) {
        aggConf = priced.reduce((s, c) => s + c, 0) / priced.length;
      }
    }

    const totalValue = totals ? totals.value : null;
    const allTimePnl = totals ? totals.allTime : null;
    const allTimePct = totals ? totals.allTimePct : null;
    const dayPnl = totals ? totals.day : null;
    const dayPct = totals ? totals.dayPct : null;

    const valueDisplay =
      totalValue !== null && totals.priced > 0 ? W.fmt.money(totalValue) : "—";
    const pnlDisplay = allTimePnl !== null ? signedMoney(allTimePnl) : "—";
    const pnlDelta = allTimePct !== null ? W.fmt.pct(allTimePct) : "—";
    const pnlDeltaCls =
      allTimePnl === null ? "muted" : allTimePnl >= 0 ? "up" : "down";

    const dayDelta = dayPct !== null ? W.fmt.pct(dayPct) : "—";
    const dayDeltaCls = dayPnl === null ? "muted" : dayPnl >= 0 ? "up" : "down";

    const confDisplay =
      aggConf === null ? "Unavailable" : `${Math.round(aggConf * 100)}%`;
    const confDeltaCls =
      aggConf === null ? "muted" : aggConf >= 0.6 ? "up" : "warn";

    return `
      <div class="kpi">
        <div class="kpi-icon kpi-icon-up" aria-hidden="true">▤</div>
        <div class="kpi-body">
          <div class="kpi-label">Total Portfolio Value</div>
          <div class="kpi-value">${esc(valueDisplay)}</div>
          <div class="kpi-delta ${dayDeltaCls}">${esc(dayDelta)} (24h)</div>
        </div>
      </div>
      <div class="kpi">
        <div class="kpi-icon ${allTimePnl === null ? "" : allTimePnl >= 0 ? "kpi-icon-up" : "kpi-icon-down"}" aria-hidden="true">◈</div>
        <div class="kpi-body">
          <div class="kpi-label">Total P&amp;L</div>
          <div class="kpi-value">${pnlDisplay}</div>
          <div class="kpi-delta ${pnlDeltaCls}">${esc(pnlDelta)}${totals && totals.unknownCost ? ` · ${totals.unknownCost} missing cost` : " · all time"}</div>
        </div>
      </div>
      <div class="kpi">
        <div class="kpi-icon" aria-hidden="true">∿</div>
        <div class="kpi-body">
          <div class="kpi-label">Active Signals</div>
          <div class="kpi-value">${esc(signalCount)}</div>
          <div class="kpi-sub">${high} high · ${mid} medium · ${low} low</div>
        </div>
      </div>
      <div class="kpi">
        <div class="kpi-icon ${confDeltaCls === "up" ? "kpi-icon-up" : confDeltaCls === "warn" ? "kpi-icon-warn" : ""}" aria-hidden="true">⛨</div>
        <div class="kpi-body">
          <div class="kpi-label">Confidence (Aggregate)</div>
          <div class="kpi-value">${esc(confDisplay)}</div>
          <div class="kpi-delta ${confDeltaCls}">${aggConf === null ? "evidence incomplete" : "across priced signals"}</div>
        </div>
      </div>
    `;
  }

  // ── Main render ───────────────────────────────────────────
  async function render(view) {
    if (!view) return;
    destroyCharts(view);

    view.innerHTML = `
      <div class="dash-hero">
        <h2 class="dash-hero-title">Dashboard</h2>
        <p class="dash-hero-sub">Real-time intelligence for smarter crypto decisions.</p>
        <p class="muted small" id="dash-updated">Last updated: ${esc(new Date().toUTCString())}</p>
      </div>

      <div class="kpi-grid" id="d-kpi">${skel.stats(4)}</div>

      <div class="dash-row-primary">
        <div class="card dash-chart-card">
          <div class="dash-card-head">
            <span class="dash-card-title">Portfolio Performance</span>
            <div class="dash-range" id="d-perf-range" role="tablist">
              <button type="button" class="dash-range-btn active" data-range="7">1W</button>
              <button type="button" class="dash-range-btn" data-range="30">1M</button>
              <button type="button" class="dash-range-btn" data-range="90">3M</button>
              <button type="button" class="dash-range-btn" data-range="365">1Y</button>
              <button type="button" class="dash-range-btn" data-range="all">ALL</button>
            </div>
          </div>
          <div class="dash-chart-canvas-wrap">
            <canvas id="d-perf-chart" aria-label="Portfolio performance chart"></canvas>
          </div>
          <p class="muted small mt-8" id="d-perf-note"></p>
        </div>
        <div class="card dash-donut-card">
          <div class="dash-card-head">
            <span class="dash-card-title">Allocation</span>
          </div>
          <div class="dash-donut-wrap">
            <canvas id="d-donut" aria-label="Portfolio allocation"></canvas>
            <div class="dash-donut-center">
              <div class="dash-donut-center-value" id="d-donut-total">—</div>
              <div class="dash-donut-center-label">Total Value</div>
            </div>
          </div>
          <div class="dash-legend" id="d-legend"></div>
        </div>
        <div class="card dash-signals-card">
          <div class="dash-card-head">
            <span class="dash-card-title">Recent Signals</span>
            <button type="button" class="dash-card-link" data-route="/market">View all →</button>
          </div>
          <div id="d-signals"></div>
        </div>
      </div>

      <div class="dash-row-secondary">
        <div class="card">
          <div class="dash-card-head">
            <span class="dash-card-title">Top Tokens</span>
            <div class="dash-range" id="d-mkt-tabs" role="tablist">
              <button type="button" class="dash-range-btn active" data-tab="top">Top</button>
              <button type="button" class="dash-range-btn" data-tab="gain">Gainers</button>
              <button type="button" class="dash-range-btn" data-tab="lose">Losers</button>
              <button type="button" class="dash-range-btn" data-tab="trending">Trending</button>
            </div>
          </div>
          <div id="d-tape"></div>
          <div class="token-header" role="row">
            <span class="token-rank">#</span>
            <span class="token-ident">Asset</span>
            <span class="token-price">Price</span>
            <span class="token-change">24h</span>
            <span class="token-mcap">Market Cap</span>
          </div>
          <div id="d-tokens"></div>
          <div id="d-market-more"></div>
        </div>
        <div class="dash-col-stack">
          <div class="card">
            <div class="dash-card-head">
              <span class="dash-card-title">Market Sentiment</span>
            </div>
            <div id="d-fg"></div>
          </div>
          <div class="card">
            <div id="d-dom"></div>
          </div>
        </div>
      </div>

      <div class="dash-row-tertiary">
        <div class="card">
          <div class="dash-card-head">
            <span class="dash-card-title">Why? / Evidence</span>
          </div>
          <p class="muted small mb-8">Understand the reasoning behind each signal.</p>
          <div id="d-evidence"></div>
        </div>
        <div class="card">
          <div class="dash-card-head">
            <span class="dash-card-title">Quick Actions</span>
          </div>
          <div id="d-actions"></div>
        </div>
      </div>

      <div class="card">
        <div class="dash-card-head">
          <span class="dash-card-title">Key Insights</span>
        </div>
        <div class="insights-grid" id="d-insights"></div>
      </div>

      <div class="grid-2 mt-16">
        <div id="what-matters-now-container" class="intelligence-feed card card-tertiary">${skel.feed(3)}</div>
        <div id="what-changed-container"><div class="card card-tertiary">${skel.card()}</div></div>
      </div>

      <div class="card card-tertiary mt-16">
        <div class="flex-between mb-8">
          <h3>Portfolio Holdings</h3>
          <div class="qa">
            <button class="btn tiny" id="qa-add">+ Add Holding</button>
            <button class="btn tiny" id="qa-sync" title="Manage synced wallets">Wallets</button>
          </div>
        </div>
        <div id="d-port">${skel.card()}</div>
      </div>
    `;

    // Static interactions. The initial [data-signal-id] handler is a
    // no-op at this point — the initial render is skeletons and no
    // signal ids exist. The real handlers are bound below, once the
    // `decisions` array has resolved.
    view.querySelectorAll("[data-route]").forEach((el) => {
      el.addEventListener("click", () => {
        const route = el.dataset.route;
        if (route) location.hash = "#" + route;
      });
    });

    const addBtn = view.querySelector("#qa-add");
    if (addBtn) addBtn.onclick = () => holdingModal();

    const syncBtn = view.querySelector("#qa-sync");
    if (syncBtn)
      syncBtn.onclick = () => {
        if (W.walletSync?.render) location.hash = "#/walletsync";
        else W.ui.toast("Wallet sync module not available", "warn");
      };

    const perfRangeEl = view.querySelector("#d-perf-range");
    if (perfRangeEl) {
      perfRangeEl.querySelectorAll("[data-range]").forEach((b) => {
        b.addEventListener("click", () => {
          perfRangeEl
            .querySelectorAll("[data-range]")
            .forEach((x) => x.classList.remove("active"));
          b.classList.add("active");
          drawPerformanceChart(view);
        });
      });
    }

    drawPerformanceChart(view);

    // ── Fetch data in parallel ──────────────────────────────
    const decisionsPromise =
      W.decisionEngine && typeof W.decisionEngine.run === "function"
        ? W.decisionEngine.run().catch(() => [])
        : Promise.resolve([]);

    const [topR, globR, fgR, pfR, decisionsR] = await Promise.allSettled([
      W.api.top(100),
      W.api.global(),
      W.api.fearGreed(),
      enrich(),
      decisionsPromise,
    ]);

    if (!view.isConnected) return;

    const TOP =
      topR.status === "fulfilled" && Array.isArray(topR.value)
        ? topR.value
        : [];
    const rows = pfR.status === "fulfilled" ? pfR.value.rows : [];
    const totals = pfR.status === "fulfilled" ? pfR.value.totals : null;
    const g = globR.status === "fulfilled" ? globR.value.data : null;
    const fg =
      fgR.status === "fulfilled" && fgR.value && fgR.value.value != null
        ? fgR.value
        : null;
    const decisions =
      decisionsR.status === "fulfilled" && Array.isArray(decisionsR.value)
        ? decisionsR.value
        : [];

    // KPI strip
    const kpiEl = view.querySelector("#d-kpi");
    if (kpiEl) kpiEl.innerHTML = renderKpiStrip(decisions, totals);

    // Allocation donut
    const alloc = buildAllocation(rows, totals);
    drawAllocationDonut(view, alloc);

    // Recent signals — the click handler now delegates to
    // openSignalDrawer, which looks up the matching DecisionPriority
    // in the current render and shapes the object the drawer needs.
    const signalsEl = view.querySelector("#d-signals");
    if (signalsEl) {
      signalsEl.innerHTML = renderSignals(decisions);
      signalsEl.querySelectorAll("[data-signal-id]").forEach((el) => {
        el.addEventListener("click", () => {
          openSignalDrawer(el.dataset.signalId, decisions);
        });
      });
    }

    // Tape
    const tapeEl = view.querySelector("#d-tape");
    if (tapeEl)
      tapeEl.innerHTML = TOP.length ? tapeHTML(TOP.slice(0, 20)) : tapeHTML([]);

    // Top tokens table
    let tab = "top";
    const drawTokens = () => {
      let list = TOP;
      if (tab === "gain")
        list = [...TOP]
          .sort(
            (a, b) =>
              (b.price_change_percentage_24h_in_currency ?? 0) -
              (a.price_change_percentage_24h_in_currency ?? 0),
          )
          .slice(0, 20);
      if (tab === "lose")
        list = [...TOP]
          .sort(
            (a, b) =>
              (a.price_change_percentage_24h_in_currency ?? 0) -
              (b.price_change_percentage_24h_in_currency ?? 0),
          )
          .slice(0, 20);
      if (tab === "trending") list = TOP.slice(0, 20);
      if (tab === "top") list = TOP.slice(0, 50);

      const fullCount = list.length;
      const visibleList = marketRowsExpanded
        ? list
        : list.slice(0, MARKET_ROWS_DEFAULT);

      const tokensEl = view.querySelector("#d-tokens");
      if (tokensEl) {
        tokensEl.innerHTML = visibleList.length
          ? visibleList.map(tokenRow).filter(Boolean).join("")
          : `<p class="muted small p-16">No market data available.</p>`;
        tokensEl.querySelectorAll("[data-coin]").forEach((el) => {
          el.addEventListener("click", () => {
            location.hash = "#/coin/" + el.dataset.coin;
          });
        });
      }

      const moreEl = view.querySelector("#d-market-more");
      if (moreEl) {
        if (fullCount > MARKET_ROWS_DEFAULT) {
          moreEl.innerHTML = marketRowsExpanded
            ? `<button type="button" class="btn tiny mt-8" id="d-market-toggle">Show top ${MARKET_ROWS_DEFAULT}</button>`
            : `<button type="button" class="btn tiny mt-8" id="d-market-toggle">Show all ${fullCount}</button>`;
          const tg = moreEl.querySelector("#d-market-toggle");
          if (tg)
            tg.addEventListener("click", () => {
              marketRowsExpanded = !marketRowsExpanded;
              drawTokens();
            });
        } else {
          moreEl.innerHTML = "";
        }
      }
    };
    view.querySelectorAll("#d-mkt-tabs [data-tab]").forEach((c) => {
      c.addEventListener("click", () => {
        view
          .querySelectorAll("#d-mkt-tabs [data-tab]")
          .forEach((x) => x.classList.remove("active"));
        c.classList.add("active");
        tab = c.dataset.tab;
        marketRowsExpanded = false;
        drawTokens();
      });
    });
    drawTokens();
    wireAvatarFallbacks(view);

    // Fear & Greed + BTC dominance
    const fgEl = view.querySelector("#d-fg");
    if (fgEl) fgEl.innerHTML = renderFearGreed(fg);

    const domEl = view.querySelector("#d-dom");
    if (domEl)
      domEl.innerHTML = g
        ? renderDominance({ data: g })
        : `<div class="dash-card-title">BTC Dominance</div><div class="dom-value">—</div><div class="dom-delta muted">Source unavailable</div>`;

    // Evidence preview — delegates to openSignalDrawer.
    const evEl = view.querySelector("#d-evidence");
    if (evEl) {
      evEl.innerHTML = renderEvidencePreview(decisions);
      evEl.querySelectorAll("[data-signal-id]").forEach((el) => {
        el.addEventListener("click", () => {
          openSignalDrawer(el.dataset.signalId, decisions);
        });
      });
    }

    // Quick actions
    const qaEl = view.querySelector("#d-actions");
    if (qaEl) {
      qaEl.innerHTML = renderQuickActions();
      qaEl.querySelectorAll("[data-route]").forEach((el) => {
        el.addEventListener("click", () => {
          const route = el.dataset.route;
          if (route) location.hash = "#" + route;
        });
      });
    }

    // Key insights — delegates to openSignalDrawer for signal items.
    const insEl = view.querySelector("#d-insights");
    if (insEl) {
      insEl.innerHTML = renderInsights(decisions, fg, rows, totals);
      insEl.querySelectorAll("[data-signal-id]").forEach((el) => {
        el.addEventListener("click", () => {
          openSignalDrawer(el.dataset.signalId, decisions);
        });
      });
      insEl.querySelectorAll("[data-route]").forEach((el) => {
        el.addEventListener("click", () => {
          const route = el.dataset.route;
          if (route) location.hash = "#" + route;
        });
      });
    }

    // Portfolio holdings
    const port = view.querySelector("#d-port");
    if (port) {
      if (!rows.length) {
        port.innerHTML =
          '<p class="text-muted small-text text-center p-24">No holdings yet. Click "+ Add Holding" above, or Sync Wallets.</p>';
      } else {
        port.innerHTML = holdingsTable(rows);
        wireRows(port, rows);
        wireAvatarFallbacks(port);
      }
    }

    // Intelligence feed
    const rankerContainer = view.querySelector("#what-matters-now-container");
    if (rankerContainer) {
      if (W.intelligenceFeed && decisions.length) {
        try {
          W.intelligenceFeed.render(rankerContainer, decisions);
        } catch (e) {
          rankerContainer.innerHTML =
            '<p class="text-muted small p-16">Intelligence feed temporarily unavailable.</p>';
        }
      } else if (W.intelligenceFeed) {
        W.intelligenceFeed.render(rankerContainer, []);
      } else {
        rankerContainer.innerHTML =
          '<p class="text-muted small p-16">Intelligence engine loading…</p>';
      }
    }

    // Discoveries + portfolio deltas
    const changedContainer = view.querySelector("#what-changed-container");
    if (changedContainer) {
      const gemTheses = (W.theses?.all?.() || [])
        .filter((t) => t.sourceRef?.type === "gem")
        .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
        .slice(0, 3);

      const discoveriesHTML = gemTheses.length
        ? `<ul class="discovery-list">${gemTheses
            .map(
              (t) => `
            <li class="discovery-item">
              <div class="discovery-head">
                <b>${esc(t.asset)}</b>
                <span class="muted small">${esc(t.signals || "Security status unavailable")}</span>
              </div>
              ${t.reasons ? `<p class="muted small mt-4">${esc(t.reasons)}</p>` : ""}
            </li>`,
            )
            .join("")}</ul>`
        : `<p class="muted small">No new discoveries yet — run Gem Agent to populate this.</p>`;

      const deltasHTML =
        totals && W.delta
          ? (() => {
              try {
                const deltas = W.delta.computePortfolioDeltas(totals);
                const container = document.createElement("div");
                W.delta.renderList(container, deltas);
                return container.innerHTML;
              } catch (e) {
                console.warn("[Dashboard] delta render failed:", e?.message);
                return `<p class="muted small">Portfolio change history unavailable.</p>`;
              }
            })()
          : `<p class="muted small">Add holdings to your portfolio to start tracking value changes over time.</p>`;

      changedContainer.innerHTML = `
        <div class="card card-tertiary">
          <h3>Discoveries</h3>
          <p class="muted small mb-8 mt-8">New intelligence</p>
          ${discoveriesHTML}
          <p class="muted small mb-8 mt-16">Portfolio changes</p>
          <div class="delta-container">${deltasHTML}</div>
        </div>
      `;

      if (totals && W.delta && totals.unpriced === 0) {
        const currentSnapshot = W.delta.getSnapshot();
        if (
          !currentSnapshot ||
          Date.now() - currentSnapshot.timestamp > 3600000
        )
          W.delta.saveSnapshot(totals);
      }
    }
  }

  function renderPortfolio(view) {
    if (!view) return;
    const has = W.portfolio ? W.portfolio.all().length > 0 : false;
    view.innerHTML = `
      <div class="card card-primary">
        <div class="flex-between mb-8">
          <h3>Holdings</h3>
          <div class="qa">
            <button class="btn primary" id="p-add">+ Add Holding</button>
          </div>
        </div>
        <div id="p-body">${has ? skel.card() : '<p class="text-muted">No holdings yet.</p>'}</div>
      </div>`;
    const addBtn = view.querySelector("#p-add");
    if (addBtn) addBtn.onclick = () => holdingModal();
    if (has) {
      enrich().then(({ rows }) => {
        if (!view.isConnected) return;
        const body = view.querySelector("#p-body");
        if (body) {
          body.innerHTML = holdingsTable(rows);
          wireRows(body, rows);
          wireAvatarFallbacks(body);
        }
      });
    }
  }

  return Object.freeze({
    render,
    renderPortfolio,
    holdingModal,
    enrich,
    version: MODULE_VERSION,
  });
})();

console.log(
  "[Dashboard] Module loaded (Command Center v3.5: real token logos with letter-avatar fallback; signal drawer passes shaped domains).",
);
// ---- js/ui/skeleton.js ----
// ===============================================================
//     Weaver Skeleton Loading States
//     Constitution §3.4: Graceful Degradation
//     Constitution §5.3: Calm Visual Language (no spinners)
// ===============================================================
// CSP-safe: no inline styles. All sizing via CSS classes.
// Respects prefers-reduced-motion via existing CSS media query.
// ===============================================================

window.W = window.W || {};
W.ui = W.ui || {};

W.ui.skeleton = (() => {
  function block(className) {
    return '<div class="skeleton ' + W.fmt.escapeHTML(className) + '"></div>';
  }

  function card() {
    return '<div class="skeleton skeleton-card"></div>';
  }

  function stat() {
    return '<div class="skeleton skeleton-stat"></div>';
  }

  function stats(count) {
    var html = "";
    for (var i = 0; i < count; i++) html += stat();
    return html;
  }

  function row() {
    return '<div class="skeleton skeleton-row"></div>';
  }

  function table(rows) {
    var html = "";
    for (var i = 0; i < rows; i++) html += row();
    return html;
  }

  function chart() {
    return '<div class="skeleton skeleton-chart"></div>';
  }

  function feedItem() {
    return '<div class="skeleton skeleton-feed-item"></div>';
  }

  function feed(items) {
    var html = "";
    for (var i = 0; i < items; i++) html += feedItem();
    return html;
  }

  return {
    block: block,
    card: card,
    stat: stat,
    stats: stats,
    row: row,
    table: table,
    chart: chart,
    feedItem: feedItem,
    feed: feed,
  };
})();

console.log("[Skeleton] Module loaded.");
// ---- js/ui/evidence-drawer.js ----
// ===============================================================
//         Weaver Evidence Drawer 
// ===============================================================


window.W = window.W || {};
W.ui = W.ui || {};

W.ui.evidenceDrawer = (() => {
  const MODULE_VERSION = "evidence-drawer-v2";

  // ── Caps ────────────────────────────────────────────────────
  // Chosen so a single drawer open cannot allocate more than a few
  // hundred KB of DOM. A legitimate evidence drawer stays well
  // under these.
  const MAX_ITEMS_PER_BUCKET = 200;
  const MAX_REASONS_PER_ITEM = 30;
  const MAX_TITLE_LEN = 200;
  const MAX_DETAIL_LEN = 2000;
  const MAX_REASON_LEN = 500;
  const MAX_META_LEN = 200;
  const MAX_DOMAINS = 500;

  // ── Escaping ───────────────────────────────────────────────
  // Safe in both text and quoted-attribute contexts. Handles
  // Symbol, BigInt, null, undefined, and objects whose toString
  // throws. Prefers W.fmt.escapeHTML when it exists and behaves
  // like a string escaper; otherwise falls back to the local
  // implementation.
  function localEsc(v) {
    if (v === null || v === undefined) return "";
    let s;
    try {
      s = String(v);
    } catch {
      // Symbol, BigInt wrappers with a broken toString, proxies
      // that trap access — return an empty string rather than
      // letting the render crash.
      return "";
    }
    if (!/[&<>"']/.test(s)) return s;
    return s
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  const esc =
    W.fmt && typeof W.fmt.escapeHTML === "function"
      ? function (v) {
          // Prefer the canonical escaper, but fall back to localEsc
          // if it throws. A hostile value should not be able to
          // disable escaping by triggering a throw inside the
          // shared helper.
          try {
            return String(W.fmt.escapeHTML(String(v ?? "")));
          } catch {
            return localEsc(v);
          }
        }
      : localEsc;

  // Safe property access. A getter that throws, a Proxy that traps
  // `get`, or a missing property all produce undefined rather than
  // an uncaught exception.
  function safeProp(obj, key) {
    if (!obj || typeof obj !== "object") return undefined;
    try {
      return obj[key];
    } catch {
      return undefined;
    }
  }

  // String coercion with a length cap. Applied before any HTML
  // wrapping, so the cap counts the visible characters, not the
  // escaped entities.
  function capStr(v, max) {
    if (v === null || v === undefined) return "";
    let s;
    try {
      s = String(v);
    } catch {
      return "";
    }
    if (s.length > max) return s.slice(0, max) + "…";
    return s;
  }

  // ── Relationship normalisation ─────────────────────────────
  const RELATIONSHIP_VALUES = Object.freeze({
    supporting: "supporting",
    contradicting: "contradicting",
    neutral: "neutral",
    unknown: "unknown",
  });

  function normalizeRelationship(value) {
    if (typeof value !== "string") return "unknown";
    const v = value.trim().toLowerCase();
    return RELATIONSHIP_VALUES[v] || "unknown";
  }

  // Prototype-pollution guard. A hostile domain name of
  // "__proto__" or "constructor" is dropped at ingest.
  const RESERVED_KEYS = new Set(["__proto__", "constructor", "prototype"]);
  function isReservedKey(k) {
    return RESERVED_KEYS.has(k);
  }

  // ── Bucketing ───────────────────────────────────────────────
  // Relationship drives the bucket. Status is preserved on the item
  // for display but does not determine where the item appears.
  //
  // "neutral" is explicitly mapped to Unknowns — the drawer has
  // three sections and neutral evidence is neither for nor against
  // the thesis.
  //
  // Item count is capped at MAX_ITEMS_PER_BUCKET. Overflow is
  // reported as a single note in the bucket rather than being
  // silently dropped.
  function bucket(domains) {
    const out = { supporting: [], contradicting: [], unknowns: [] };
    if (!domains || typeof domains !== "object" || Array.isArray(domains)) {
      return out;
    }

    let inspected = 0;
    const keys = (() => {
      try {
        return Object.keys(domains);
      } catch {
        return [];
      }
    })();

    for (const name of keys) {
      if (inspected++ >= MAX_DOMAINS) break;
      if (isReservedKey(name)) continue;

      const d = safeProp(domains, name);
      if (!d || typeof d !== "object") {
        // A non-object domain value is recorded as unknown rather
        // than dropped — the reader sees that something existed
        // there but could not be interpreted.
        out.unknowns.push({
          name: capStr(name, MAX_TITLE_LEN),
          status: "unknown",
          source: undefined,
          observedAt: undefined,
          freshness: undefined,
          methodologyVersion: undefined,
          relationship: "unknown",
          reliability: undefined,
          reasons: [],
        });
        continue;
      }

      const relationship = normalizeRelationship(safeProp(d, "relationship"));
      const rawReasons = safeProp(d, "reasons");
      const reasons = Array.isArray(rawReasons)
        ? rawReasons
            .slice(0, MAX_REASONS_PER_ITEM)
            .map((r) => capStr(r, MAX_REASON_LEN))
            .filter(Boolean)
        : [];

      const e = {
        name: capStr(name, MAX_TITLE_LEN),
        status: capStr(safeProp(d, "status") || "unknown", MAX_META_LEN),
        source: capStr(safeProp(d, "source"), MAX_META_LEN) || undefined,
        observedAt: safeProp(d, "observedAt") || safeProp(d, "asOf"),
        freshness: safeProp(d, "freshness"),
        methodologyVersion:
          capStr(safeProp(d, "methodologyVersion"), MAX_META_LEN) || undefined,
        relationship,
        reliability: safeProp(d, "reliability"),
        reasons,
      };

      if (relationship === "supporting") out.supporting.push(e);
      else if (relationship === "contradicting") out.contradicting.push(e);
      else out.unknowns.push(e);
    }

    // Enforce the per-bucket cap after sorting. Overflow produces a
    // synthetic note rather than dropping the excess silently.
    for (const k of Object.keys(out)) {
      if (out[k].length > MAX_ITEMS_PER_BUCKET) {
        const overflow = out[k].length - MAX_ITEMS_PER_BUCKET;
        out[k] = out[k].slice(0, MAX_ITEMS_PER_BUCKET);
        out[k].push({
          name: `+${overflow} more not shown`,
          status: "overflow",
          relationship: "unknown",
          reasons: [],
        });
      }
    }

    return out;
  }

  // ── Provenance rendering ────────────────────────────────────
  // Every field renders. Missing values become the literal string
  // "unknown" — they are never omitted, because an omitted field
  // reads as "not applicable" rather than "not known".
  function formatProvenanceField(label, rawValue) {
    const v =
      rawValue === null || rawValue === undefined || rawValue === ""
        ? "unknown"
        : capStr(rawValue, MAX_META_LEN);
    return label + ": " + v;
  }

  function formatPercent(value) {
    return Number.isFinite(value) ? Math.round(value * 100) + "%" : null;
  }

  function formatDate(value) {
    if (!value) return null;
    // Guard the type check before constructing a Date. Symbol and
    // BigInt cannot be passed to new Date() without throwing.
    if (typeof value !== "string" && typeof value !== "number") return null;
    try {
      const d = new Date(value);
      if (!Number.isFinite(d.getTime())) return null;
      return d.toLocaleString();
    } catch (_) {
      return null;
    }
  }

  function renderProvenance(it) {
    const fields = [
      formatProvenanceField("Source", it.source),
      formatProvenanceField("Observed", formatDate(it.observedAt)),
      formatProvenanceField("Freshness", formatPercent(it.freshness)),
      formatProvenanceField("Methodology", it.methodologyVersion),
      formatProvenanceField("Relationship", it.relationship),
      formatProvenanceField("Reliability", formatPercent(it.reliability)),
    ];
    return '<p class="muted text-2xs mt-4">' + esc(fields.join(" · ")) + "</p>";
  }

  function renderItems(items, empty) {
    if (!Array.isArray(items) || !items.length) {
      return '<p class="muted small">' + esc(empty) + "</p>";
    }
    return (
      '<ul class="tx-list">' +
      items
        .map((it) => {
          if (!it || typeof it !== "object") return "";
          const title = capStr(
            it.title || it.name || "Evidence",
            MAX_TITLE_LEN,
          );
          const meta = capStr(it.status || "", MAX_META_LEN);
          const detail = capStr(it.detail || it.evidence || "", MAX_DETAIL_LEN);
          const reasons = (Array.isArray(it.reasons) ? it.reasons : [])
            .slice(0, MAX_REASONS_PER_ITEM)
            .map(
              (r) =>
                '<p class="muted small mt-4">• ' +
                esc(capStr(r, MAX_REASON_LEN)) +
                "</p>",
            )
            .join("");
          return (
            '<li><div class="flex-between"><b>' +
            esc(title) +
            '</b><span class="muted small">' +
            esc(meta) +
            "</span></div>" +
            renderProvenance(it) +
            (detail
              ? '<p class="muted small mt-4">' + esc(detail) + "</p>"
              : "") +
            reasons +
            "</li>"
          );
        })
        .join("") +
      "</ul>"
    );
  }

  // Carry provenance fields from a source evidence object onto the
  // drawer item, so renderItems() has all six fields regardless of
  // which layer produced the item.
  //
  // relationship is NOT defaulted to "supporting" here — a caller
  // that produced bullish evidence has already declared that
  // relationship upstream, and this carry function preserves it.
  //
  // Reads go through safeProp; a source with a throwing getter
  // yields undefined rather than crashing.
  function carryProvenance(item, source) {
    const s = source && typeof source === "object" ? source : {};
    const i = item && typeof item === "object" ? item : {};
    const pick = (key) => {
      const iv = safeProp(i, key);
      if (iv !== undefined) return iv;
      return safeProp(s, key);
    };
    return {
      title: capStr(pick("title") || pick("name") || "Evidence", MAX_TITLE_LEN),
      detail: capStr(pick("detail") || pick("evidence") || "", MAX_DETAIL_LEN),
      source: capStr(pick("source"), MAX_META_LEN) || undefined,
      observedAt: pick("observedAt") || pick("timestamp") || undefined,
      freshness: pick("freshness"),
      methodologyVersion:
        capStr(pick("methodologyVersion"), MAX_META_LEN) || undefined,
      relationship: normalizeRelationship(pick("relationship")),
      reliability: pick("reliability"),
      reasons: (Array.isArray(pick("reasons")) ? pick("reasons") : [])
        .slice(0, MAX_REASONS_PER_ITEM)
        .map((r) => capStr(r, MAX_REASON_LEN))
        .filter(Boolean),
      status: capStr(pick("status"), MAX_META_LEN) || undefined,
    };
  }

  // ── Optional lines ─────────────────────────────────────────
  // Each renderer returns "" when no summary is supplied, so the
  // caller can concatenate the result unconditionally.

  function renderTrajectoryLine(summary) {
    if (typeof summary !== "string" || !summary.trim()) return "";
    return (
      '<p class="small"><b>Trajectory:</b> ' +
      esc(capStr(summary, MAX_DETAIL_LEN)) +
      "</p>"
    );
  }

  function renderOwnerLine(summary) {
    if (typeof summary !== "string" || !summary.trim()) return "";
    return (
      '<p class="small"><b>Owner:</b> ' +
      esc(capStr(summary, MAX_DETAIL_LEN)) +
      "</p>"
    );
  }

  function renderDeployerLine(summary) {
    if (typeof summary !== "string" || !summary.trim()) return "";
    return (
      '<p class="small"><b>Deployer:</b> ' +
      esc(capStr(summary, MAX_DETAIL_LEN)) +
      "</p>"
    );
  }

  function renderTrackRecordLine(summary) {
    if (typeof summary !== "string" || !summary.trim()) return "";
    return (
      '<p class="small"><b>Your Track Record:</b> ' +
      esc(capStr(summary, MAX_DETAIL_LEN)) +
      "</p>"
    );
  }

  // ── Top-level open ─────────────────────────────────────────
  function open(result) {
    const r = result && typeof result === "object" ? result : {};

    let b;
    try {
      b = bucket(safeProp(r, "domains"));
    } catch (e) {
      console.warn("[EvidenceDrawer] bucket failed:", e && e.message);
      b = { supporting: [], contradicting: [], unknowns: [] };
    }

    const readSummary = (key) => {
      const v = safeProp(r, key);
      return typeof v === "string" && v.trim()
        ? capStr(v, MAX_DETAIL_LEN)
        : null;
    };

    const trajectorySummary = readSummary("trajectorySummary");
    const ownerSummary = readSummary("ownerSummary");
    const deployerSummary = readSummary("deployerSummary");
    const trackRecordSummary = readSummary("trackRecordSummary");

    // Build each bucket with a try/catch per map step so one
    // malformed entry cannot blank the entire section.
    const safeArrayMap = (raw, mapper) => {
      if (!Array.isArray(raw)) return [];
      const out = [];
      for (const item of raw.slice(0, MAX_ITEMS_PER_BUCKET)) {
        try {
          out.push(mapper(item));
        } catch (e) {
          console.warn("[EvidenceDrawer] item map failed:", e && e.message);
        }
      }
      return out;
    };

    const supporting = [
      ...safeArrayMap(safeProp(r, "bullishEvidence"), (e) =>
        carryProvenance(
          {
            title: safeProp(e, "title"),
            detail: safeProp(e, "evidence"),
            status: "supporting",
            relationship: "supporting",
          },
          e,
        ),
      ),
      ...b.supporting,
    ];

    const contradicting = [
      ...safeArrayMap(safeProp(r, "bearishEvidence"), (e) =>
        carryProvenance(
          {
            title: safeProp(e, "title"),
            detail: safeProp(e, "evidence"),
            status: "contradicting",
            relationship: "contradicting",
          },
          e,
        ),
      ),
      ...safeArrayMap(safeProp(r, "contradictions"), (c) => {
        const bull = capStr(safeProp(c, "bull"), MAX_TITLE_LEN);
        const bear = capStr(safeProp(c, "bear"), MAX_TITLE_LEN);
        return carryProvenance({
          title: bull + " vs " + bear,
          detail: safeProp(c, "details"),
          status: "contradicting",
          relationship: "contradicting",
        });
      }),
      ...b.contradicting,
    ];

    const eqReasons = (() => {
      const eq = safeProp(r, "evidenceQuality");
      const reasons = safeProp(eq, "reasons");
      return Array.isArray(reasons) ? reasons : [];
    })();

    const unknowns = [
      ...b.unknowns,
      ...safeArrayMap(eqReasons, (x) =>
        carryProvenance({
          title: "Evidence gap",
          detail: x,
          relationship: "unknown",
        }),
      ),
    ];

    const meta = [
      safeProp(r, "methodologyVersion")
        ? "Methodology " +
          capStr(safeProp(r, "methodologyVersion"), MAX_META_LEN)
        : null,
      safeProp(r, "evidenceVersion")
        ? "Evidence " + capStr(safeProp(r, "evidenceVersion"), MAX_META_LEN)
        : null,
    ]
      .filter(Boolean)
      .join(" · ");

    const explanation = capStr(
      safeProp(r, "explanation") || "Evidence behind the current scenario.",
      MAX_DETAIL_LEN,
    );

    const body =
      '<p class="small muted">' +
      esc(explanation) +
      "</p>" +
      (meta ? '<p class="small muted">' + esc(meta) + "</p>" : "") +
      renderTrajectoryLine(trajectorySummary) +
      renderOwnerLine(ownerSummary) +
      renderDeployerLine(deployerSummary) +
      renderTrackRecordLine(trackRecordSummary) +
      '<div class="mt-12">' +
      "<h4>🟢 Supporting evidence</h4>" +
      renderItems(supporting, "None recorded.") +
      "<h4>🔴 Contradicting evidence</h4>" +
      renderItems(contradicting, "None recorded.") +
      "<h4>❓ Unknowns</h4>" +
      renderItems(unknowns, "No evidence gaps recorded.") +
      "</div>";

    // The modal call is wrapped. If W.ui.modal is missing or throws,
    // the drawer falls back to a plain-text notice rather than
    // leaving the user with a blank screen and no explanation.
    if (!W.ui || typeof W.ui.modal !== "function") {
      console.warn("[EvidenceDrawer] W.ui.modal is unavailable.");
      return null;
    }

    let m;
    try {
      m = W.ui.modal({
        title: "Why this verdict?",
        body,
        footer: '<button class="btn ghost" data-a="close">Close</button>',
      });
    } catch (e) {
      console.warn("[EvidenceDrawer] modal failed:", e && e.message);
      return null;
    }

    if (m && m.el) {
      const btn = m.el.querySelector('[data-a="close"]');
      if (btn) btn.onclick = m.close;
    }
    return m;
  }

  // ── Public API ─────────────────────────────────────────────
  return Object.freeze({
    open,
    version: MODULE_VERSION,
    // Exposed for tests only. Frozen.
    _internal: Object.freeze({
      bucket,
      renderItems,
      renderProvenance,
      renderTrajectoryLine,
      renderOwnerLine,
      renderDeployerLine,
      renderTrackRecordLine,
      carryProvenance,
      normalizeRelationship,
      esc,
      safeProp,
      capStr,
      isReservedKey,
      constants: Object.freeze({
        MAX_ITEMS_PER_BUCKET,
        MAX_REASONS_PER_ITEM,
        MAX_TITLE_LEN,
        MAX_DETAIL_LEN,
        MAX_REASON_LEN,
        MAX_META_LEN,
        MAX_DOMAINS,
      }),
    }),
  });
})();

console.log(
  "[EvidenceDrawer] Module loaded (evidence-drawer-v2: correct escaper, capped strings, prototype-safe, robust against throwing getters).",
);
// ---- js/ui/intelligence-feed.js ----
// ===============================================================      
// //     Intelligence Feed — "What Matters Now" 
// ===============================================================

window.W = window.W || {};

W.intelligenceFeed = (() => {
  const MODULE_VERSION = "intelligence-feed-v2";

  // ── Caps ────────────────────────────────────────────────────
  const MAX_DECISIONS = 100;
  const MAX_REASONING_ITEMS = 20;
  const MAX_TITLE_LEN = 400;
  const MAX_REASON_LEN = 300;
  const MAX_SIGNAL_LEN = 80;

  // ── Escaping ───────────────────────────────────────────────
  // Local implementation first, then prefer W.fmt.escapeHTML if it
  // exists and behaves. Cannot throw.
  function localEsc(v) {
    if (v === null || v === undefined) return "";
    let s;
    try {
      s = String(v);
    } catch {
      return "";
    }
    if (!/[&<>"']/.test(s)) return s;
    return s
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  const esc =
    W.fmt && typeof W.fmt.escapeHTML === "function"
      ? function (v) {
          try {
            return String(W.fmt.escapeHTML(String(v ?? "")));
          } catch {
            return localEsc(v);
          }
        }
      : localEsc;

  function capStr(v, max) {
    if (v === null || v === undefined) return "";
    let s;
    try {
      s = String(v);
    } catch {
      return "";
    }
    if (s.length > max) return s.slice(0, max) + "…";
    return s;
  }

  function safeProp(obj, key) {
    if (!obj || typeof obj !== "object") return undefined;
    try {
      return obj[key];
    } catch {
      return undefined;
    }
  }

  // ── Constitutional action labels ───────────────────────────
  // §2.4 / §4.3: "EXECUTE_TRADE" is NEVER shown to the user.
  //
  // Null-prototype objects so a lookup for "__proto__" or
  // "constructor" cannot reach Object.prototype.
  const ACTION_LABELS = (() => {
    const o = Object.create(null);
    o.MONITOR = "Monitor";
    o.REVIEW_THESIS = "Review Thesis";
    o.REBALANCE = "Review Allocation";
    o.EXECUTE_TRADE = "Review Position";
    o.LOG_DECISION = "Log Decision";
    o.REVIEW = "Review";
    o.ACT = "Review";
    o.EXIT = "Review";
    o.IGNORE = "Ignore";
    return Object.freeze(o);
  })();

  const ACTION_CLASSES = (() => {
    const o = Object.create(null);
    o.MONITOR = "priority-monitor";
    o.REVIEW_THESIS = "priority-review";
    o.REBALANCE = "priority-review";
    o.EXECUTE_TRADE = "priority-risk";
    o.LOG_DECISION = "priority-log";
    o.REVIEW = "priority-review";
    o.ACT = "priority-review";
    o.EXIT = "priority-risk";
    o.IGNORE = "priority-monitor";
    return Object.freeze(o);
  })();

  function lookup(map, key, fallback) {
    if (typeof key !== "string") return fallback;
    if (!Object.prototype.hasOwnProperty.call(map, key)) return fallback;
    return map[key];
  }

  // ── Confidence helpers ─────────────────────────────────────
  function isValidConfidence(c) {
    return typeof c === "number" && Number.isFinite(c);
  }

  function confidenceBucket(confidence) {
    if (!isValidConfidence(confidence)) return null;
    const pct = Math.max(0, Math.min(100, Math.round(confidence * 100)));
    return Math.round(pct / 10) * 10;
  }

  function confidenceColor(confidence) {
    if (!isValidConfidence(confidence)) return "muted";
    if (confidence >= 0.7) return "up";
    if (confidence >= 0.4) return "warn";
    return "down";
  }

  function renderConfidenceBar(confidence) {
    if (!isValidConfidence(confidence)) {
      return (
        '<div class="feed-confidence">' +
        '<span class="feed-confidence-label">Evidence strength unavailable</span>' +
        "</div>"
      );
    }
    const bucket = confidenceBucket(confidence);
    const color = confidenceColor(confidence);
    const pct = Math.round(confidence * 100);
    return (
      '<div class="feed-confidence">' +
      '<span class="feed-confidence-label">Evidence</span>' +
      '<div class="meter-bar feed-meter">' +
      '<div class="meter-fill meter-fill-' +
      bucket +
      " meter-fill-" +
      color +
      '"></div>' +
      "</div>" +
      '<span class="feed-confidence-label">' +
      pct +
      "%</span>" +
      "</div>"
    );
  }

  // ── Item rendering ─────────────────────────────────────────
  function renderItem(decision, index) {
    if (!decision || typeof decision !== "object") return "";

    const actionRaw =
      typeof decision.recommendedAction === "string"
        ? decision.recommendedAction
        : "MONITOR";
    const actionLabelRaw = lookup(ACTION_LABELS, actionRaw, "Monitor");
    const actionClass = lookup(ACTION_CLASSES, actionRaw, "priority-monitor");

    const title = capStr(
      decision.explanation || decision._signalTitle || "Signal detected",
      MAX_TITLE_LEN,
    );
    const asset = capStr(decision._assetSymbol || "", MAX_SIGNAL_LEN);
    const signalType = capStr(decision._signalType || "", MAX_SIGNAL_LEN);

    const assessment =
      decision.assessment && typeof decision.assessment === "object"
        ? decision.assessment
        : null;

    const rawReasoning = assessment ? safeProp(assessment, "reasoning") : null;
    const reasoningList = Array.isArray(rawReasoning)
      ? rawReasoning.slice(0, MAX_REASONING_ITEMS)
      : [];

    const reasoningHTML = reasoningList.length
      ? '<div class="feed-reasoning">' +
        reasoningList.map((r) => esc(capStr(r, MAX_REASON_LEN))).join(" · ") +
        "</div>"
      : "";

    const confidence = assessment ? safeProp(assessment, "confidence") : null;

    return (
      '<div class="feed-item" data-index="' +
      index +
      '" tabindex="0" role="button" ' +
      'aria-label="View evidence for ' +
      esc(asset || "signal") +
      '">' +
      '<div class="feed-item-header">' +
      '<span class="feed-item-title">' +
      (asset ? esc(asset) + " · " : "") +
      esc(title) +
      "</span>" +
      '<span class="priority-badge ' +
      actionClass +
      '">' +
      esc(actionLabelRaw) +
      "</span>" +
      "</div>" +
      (signalType
        ? '<div class="small-text text-muted">' + esc(signalType) + "</div>"
        : "") +
      reasoningHTML +
      renderConfidenceBar(confidence) +
      "</div>"
    );
  }

  // ── Drawer wiring ──────────────────────────────────────────
  function openEvidenceDrawer(d, decisions) {
    if (!W.ui || typeof W.ui.evidenceDrawer?.open !== "function") return;
    try {
      W.ui.evidenceDrawer.open({
        title: d._assetSymbol || "Signal Details",
        subtitle: d._signalType || "",
        verdict: {
          score:
            typeof d.score === "number" && Number.isFinite(d.score)
              ? Math.round(d.score * 100)
              : null,
          confidence:
            d.assessment && typeof d.assessment === "object"
              ? d.assessment.confidence
              : null,
          classification: lookup(
            ACTION_LABELS,
            d.recommendedAction,
            "Unclassified",
          ),
          evidenceQuality:
            d.eligibility === "ELIGIBLE" ? "SUFFICIENT" : "INSUFFICIENT",
        },
        reasoning: Array.isArray(d.assessment?.reasoning)
          ? d.assessment.reasoning
          : [],
        risks: [],
        evidence: null,
        sources: [],
        methodology: d.methodologyVersion || "decision-engine-v1",
        timestamp: Date.now(),
      });
    } catch (e) {
      console.warn("[IntelligenceFeed] drawer open failed:", e && e.message);
    }
  }

  // ── Public render ──────────────────────────────────────────
  function render(container, decisions) {
    if (!container || typeof container !== "object") return;

    try {
      const list = Array.isArray(decisions)
        ? decisions.slice(0, MAX_DECISIONS)
        : [];

      if (!list.length) {
        container.innerHTML =
          '<div class="card">' +
          '<p class="text-muted small">' +
          "No actionable intelligence at this time. " +
          "Weaver will surface signals here when evidence warrants your attention." +
          "</p>" +
          "</div>";
        return;
      }

      let html = "";
      for (let i = 0; i < list.length; i++) {
        try {
          html += renderItem(list[i], i);
        } catch (e) {
          console.warn(
            "[IntelligenceFeed] item render failed at index " + i + ":",
            e && e.message,
          );
        }
      }
      container.innerHTML = html;

      container.querySelectorAll(".feed-item").forEach(function (item) {
        const handler = function () {
          const idx = parseInt(item.dataset.index, 10);
          if (!Number.isInteger(idx) || idx < 0 || idx >= list.length) return;
          const d = list[idx];
          if (!d) return;
          openEvidenceDrawer(d, list);
        };

        item.addEventListener("click", handler);
        item.addEventListener("keydown", function (e) {
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault();
            handler();
          }
        });
      });
    } catch (e) {
      console.warn("[IntelligenceFeed] render failed:", e && e.message);
      try {
        container.innerHTML =
          '<div class="card">' +
          '<p class="text-muted small">' +
          "Intelligence feed could not be rendered." +
          "</p>" +
          "</div>";
      } catch {
        /* container itself is unusable; nothing else to do */
      }
    }
  }

  return Object.freeze({
    render,
    version: MODULE_VERSION,
    _internal: Object.freeze({
      esc,
      localEsc,
      capStr,
      safeProp,
      lookup,
      confidenceBucket,
      confidenceColor,
      renderConfidenceBar,
      renderItem,
      ACTION_LABELS,
      ACTION_CLASSES,
      constants: Object.freeze({
        MAX_DECISIONS,
        MAX_REASONING_ITEMS,
        MAX_TITLE_LEN,
        MAX_REASON_LEN,
        MAX_SIGNAL_LEN,
      }),
    }),
  });
})();

console.log(
  "[IntelligenceFeed] Module loaded (intelligence-feed-v2: safe escaper, prototype-safe maps, capped strings).",
);
// ---- js/api/schemas.js ----
// ===============================================================
// Runtime API schemas and freshness metadata
// ===============================================================

window.W = window.W || {};

W.dataHealth = (() => {
  const resources = {};
  const DEFAULT_STALE_AFTER = 30 * 60 * 1000;

  function mark(
    resource,
    {
      source = "unknown",
      observedAt = Date.now(),
      staleAfter = DEFAULT_STALE_AFTER,
    } = {},
  ) {
    const timestamp =
      typeof observedAt === "number" ? observedAt : Date.parse(observedAt);
    resources[resource] = {
      resource,
      source,
      observedAt: Number.isFinite(timestamp) ? timestamp : Date.now(),
      staleAfter,
      updatedAt: Date.now(),
    };
    return resources[resource];
  }

  function get(resource) {
    const item = resources[resource];
    if (!item)
      return {
        resource,
        source: "unknown",
        state: "unknown",
        ageMs: null,
        observedAt: null,
      };
    const ageMs = Math.max(0, Date.now() - item.observedAt);
    return {
      ...item,
      ageMs,
      state: ageMs > item.staleAfter ? "stale" : "fresh",
    };
  }

  function all() {
    return Object.keys(resources).map(get);
  }
  function isStale(resource) {
    return get(resource).state === "stale";
  }
  return { mark, get, all, isStale };
})();

W.schemas = (() => {
  class SchemaValidationError extends Error {
    constructor(name, message) {
      super(`${name}: ${message}`);
      this.name = "SchemaValidationError";
      this.schema = name;
    }
  }

  const isObject = (v) =>
    v !== null && typeof v === "object" && !Array.isArray(v);
  const isFiniteNumber = (v) => typeof v === "number" && Number.isFinite(v);
  const optionalNumber = (v) =>
    v === null || v === undefined || isFiniteNumber(v);
  const requiredString = (v) => typeof v === "string" && v.length > 0;

  function assert(name, condition, message) {
    if (!condition) throw new SchemaValidationError(name, message);
  }

  function marketCoin(value, name = "market coin") {
    assert(name, isObject(value), "expected an object");
    assert(name, requiredString(value.id), "id must be a non-empty string");
    assert(
      name,
      requiredString(value.symbol),
      "symbol must be a non-empty string",
    );
    assert(
      name,
      isFiniteNumber(value.current_price),
      "current_price must be a finite number",
    );
    assert(
      name,
      optionalNumber(value.market_cap),
      "market_cap must be numeric or null",
    );
    return value;
  }

  function markets(value) {
    assert(
      "market listings",
      Array.isArray(value) && value.length > 0,
      "expected a non-empty array",
    );
    value.forEach((coin, index) =>
      marketCoin(coin, `markets[${index}]`),
    );
    return value;
  }

  function global(value) {
    assert(
      "global market",
      isObject(value) && isObject(value.data),
      "data must be an object",
    );
    const data = value.data;
    assert(
      "global market",
      isObject(data.total_market_cap),
      "total_market_cap is required",
    );
    assert(
      "global market",
      optionalNumber(data.market_cap_change_percentage_24h_usd),
      "market cap change must be numeric",
    );
    return value;
  }

  function fearGreed(value) {
    assert(
      "Fear and Greed",
      isObject(value) && Array.isArray(value.data) && value.data.length > 0,
      "data must be a non-empty array",
    );
    const item = value.data[0];
    assert(
      "Fear and Greed",
      requiredString(String(item.value ?? "")),
      "value is required",
    );
    assert(
      "Fear and Greed",
      requiredString(item.value_classification),
      "value_classification is required",
    );
    return value;
  }

  function search(value) {
    assert(
      "search",
      isObject(value) && Array.isArray(value.coins),
      "coins must be an array",
    );
    value.coins.forEach((coin, index) => {
      assert(
        "search",
        isObject(coin) && requiredString(coin.id),
        `coins[${index}].id is required`,
      );
    });
    return value;
  }

  function coin(value) {
    assert(
      "coin",
      isObject(value) && requiredString(value.id),
      "id is required",
    );
    assert(
      "coin",
      requiredString(value.symbol),
      "symbol is required",
    );
    assert(
      "coin",
      isObject(value.market_data),
      "market_data is required",
    );
    return value;
  }

  function chart(value) {
    assert(
      "chart",
      isObject(value) && Array.isArray(value.prices),
      "prices must be an array",
    );
    value.prices.forEach((point, index) => {
      assert(
        "chart",
        Array.isArray(point) &&
          point.length >= 2 &&
          isFiniteNumber(point[0]) &&
          isFiniteNumber(point[1]),
        `prices[${index}] must be [timestamp, price]`,
      );
    });
    return value;
  }

  function trending(value) {
    assert(
      "trending",
      isObject(value) && Array.isArray(value.coins),
      "coins must be an array",
    );
    return value;
  }

  function binanceTickers(value) {
    assert(
      "Binance tickers",
      Array.isArray(value) && value.length > 0,
      "expected a non-empty array",
    );
    value.forEach((item, index) => {
      assert(
        "Binance tickers",
        isObject(item) && requiredString(item.symbol),
        `tickers[${index}].symbol is required`,
      );
      assert(
        "Binance tickers",
        requiredString(item.lastPrice) &&
          Number.isFinite(Number(item.lastPrice)),
        `tickers[${index}].lastPrice must be numeric`,
      );
    });
    return value;
  }

  function binanceKlines(value) {
    assert("Binance klines", Array.isArray(value), "expected an array");
    value.forEach((item, index) =>
      assert(
        "Binance klines",
        Array.isArray(item) &&
          item.length >= 5 &&
          Number.isFinite(Number(item[0])) &&
          Number.isFinite(Number(item[4])),
        `klines[${index}] is invalid`,
      ),
    );
    return value;
  }

  function goplus(value) {
    assert(
      "GoPlus security",
      isObject(value) && Number(value.code) === 1,
      "successful response code is required",
    );
    assert(
      "GoPlus security",
      isObject(value.result),
      "result must be an object",
    );
    return value;
  }

  function blockscoutCollection(value) {
    assert(
      "Blockscout collection",
      isObject(value) && Array.isArray(value.items),
      "items must be an array",
    );
    return value;
  }

  function blockscoutToken(value) {
    assert("Blockscout token", isObject(value), "expected an object");
    return value;
  }

  function jsonRpc(value) {
    assert(
      "JSON-RPC",
      isObject(value) && value.jsonrpc === "2.0",
      "jsonrpc 2.0 response is required",
    );
    assert(
      "JSON-RPC",
      value.error === undefined || isObject(value.error),
      "error must be an object when present",
    );
    assert(
      "JSON-RPC",
      value.result !== undefined || value.error !== undefined,
      "result or error is required",
    );
    return value;
  }

  function bitcoinAddress(value) {
    assert(
      "Bitcoin address",
      isObject(value) && isObject(value.chain_stats),
      "chain_stats is required",
    );
    assert(
      "Bitcoin address",
      Number.isFinite(Number(value.chain_stats.funded_txo_sum)) &&
        Number.isFinite(Number(value.chain_stats.spent_txo_sum)),
      "chain stats must be numeric",
    );
    return value;
  }

  function telegram(value) {
    assert(
      "Telegram API",
      isObject(value) && value.ok === true,
      "successful Telegram response is required",
    );
    return value;
  }

  function llm(value) {
    assert("LLM response", isObject(value), "expected an object");
    assert(
      "LLM response",
      Array.isArray(value.choices) ||
        Array.isArray(value.content) ||
        typeof value.text === "string",
      "no supported completion payload found",
    );
    return value;
  }

  function dexPairs(value) {
    assert(
      "DEX Screener",
      isObject(value) && Array.isArray(value.pairs),
      "pairs must be an array",
    );
    return value;
  }

  function categories(value) {
    assert("categories", Array.isArray(value), "expected an array");
    value.forEach((item, index) =>
      assert(
        "categories",
        isObject(item) && requiredString(item.id),
        `categories[${index}].id is required`,
      ),
    );
    return value;
  }

  function bscscan(value) {
    assert(
      "BscScan",
      isObject(value) &&
        requiredString(String(value.status ?? "")) &&
        value.result !== undefined,
      "status and result are required",
    );
    return value;
  }

  function newsSnapshot(value) {
    assert("News snapshot", Array.isArray(value), "expected an array");
    value.forEach((item, index) =>
      assert(
        "News snapshot",
        isObject(item) &&
          requiredString(item.title) &&
          requiredString(item.link),
        `items[${index}] is invalid`,
      ),
    );
    return value;
  }

  function validate(name, value) {
    const validators = {
      markets,
      global,
      fearGreed,
      search,
      coin,
      chart,
      trending,
      binanceTickers,
      binanceKlines,
      goplus,
      blockscoutCollection,
      blockscoutToken,
      jsonRpc,
      bitcoinAddress,
      telegram,
      llm,
      dexPairs,
      categories,
      bscscan,
      newsSnapshot,
    };
    assert("Schema", validators[name], `unknown schema ${name}`);
    return validators[name](value);
  }

  return {
    SchemaValidationError,
    validate,
    markets,
    global,
    fearGreed,
    search,
    coin,
    chart,
    trending,
    binanceTickers,
    binanceKlines,
    goplus,
    blockscoutCollection,
    blockscoutToken,
    jsonRpc,
    bitcoinAddress,
    telegram,
    llm,
    dexPairs,
    categories,
    bscscan,
    newsSnapshot,
  };
})();

